/* 2003年6月9日 厚生委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"h15-20030609-7","dateIso":"2003-06-09","title":"2003年6月9日 厚生委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3048#one","fetchedAt":"2026-08-14","characters":67608,"voices":[{"i":1,"speaker":"塚本委員長","text":"○午後１時０５分開会\nただいまから、厚生委員会を開会いたします。\n審査予定表のとおり、幹部職員の紹介の後、各事業部の事務事業概要および報告事項９件を予定しております。大変各事業盛りだくさんでございます。概要の説明、長時間の説明にわたろうかと思いますし、また報告事項も件数が多うございます。めり張りをつけて聴取、またご質疑をいただきたいと思います。\nなお、本日２名の傍聴申請がございます。これを許可いたしましたので、ご承知おきください。\n────────────────────────────────────────────\n１．幹部職員紹介"},{"i":2,"speaker":"塚本委員長","text":"まず、前回委員会構成後、ございましたけれど、実質審議は初めて、また職員もそろったのは初めてという機会でございますので、各委員のほうから改めまして自己紹介をし、後に職員の紹介という手順にいたしたいと思いますので、よろしくお願いいたします。\nそれでは、私のほうから。本年度、委員長を仰せつかりました自民党の塚本でございます。どうぞよろしくお願い申し上げます。"},{"i":3,"speaker":"飯沼副委員長","text":"副委員長を務めます共産党の飯沼雅子です。よろしくお願いいたします。"},{"i":4,"speaker":"須藤委員","text":"自民党の須藤です。よろしくお願いいたします。"},{"i":5,"speaker":"大沢委員","text":"自民党の大沢真一です。よろしくお願いいたします。"},{"i":6,"speaker":"大西委員","text":"自由党の大西光広です。よろしくお願いいたします。"},{"i":7,"speaker":"三上委員","text":"公明党の三上でございます。よろしくお願いします。"},{"i":8,"speaker":"若林委員","text":"公明党の若林です。よろしくお願いします。"},{"i":9,"speaker":"鈴木（ひ）委員","text":"共産党の鈴木ひろ子です。よろしくお願いいたします。"},{"i":10,"speaker":"塚本委員長","text":"それでは、理事者のほうをお願いいたします。"},{"i":11,"speaker":"小沼福祉事業部長","text":"私のほうから、福祉事業部関係の幹部職員の紹介をさせていただきたいと思います。\n申し遅れました。初めに、私、福祉事業部長の小沼でございます。ひとつよろしくお願いいたします。\nそれから、組織順の紹介をさせていただければと思いますが、障害者福祉課長の日下部でございます。"},{"i":12,"speaker":"日下部障害者福祉課長","text":"日下部でございます。どうぞよろしくお願いいたします。"},{"i":13,"speaker":"小沼福祉事業部長","text":"続きまして、生活福祉課長の黒田でございます。"},{"i":14,"speaker":"黒田生活福祉課長","text":"黒田でございます。よろしくお願いします。"},{"i":15,"speaker":"小沼福祉事業部長","text":"児童関係の部門にいきまして、児童課長の辻田でございます。"},{"i":16,"speaker":"辻田児童課長","text":"辻田です。よろしくお願いいたします。"},{"i":17,"speaker":"小沼福祉事業部長","text":"保育課長の金子でございます。"},{"i":18,"speaker":"金子保育課長","text":"金子でございます。よろしくお願いいたします。"},{"i":19,"speaker":"小沼福祉事業部長","text":"それから、派遣になりますが、社会福祉協議会のほうへ派遣されております中川原でございます。"},{"i":20,"speaker":"中川原福祉事業部副参事","text":"中川原でございます。よろしくお願いいたします。"},{"i":21,"speaker":"小沼福祉事業部長","text":"以上、私を含めて６名でございますが、よろしくお願いしたいと思います。"},{"i":22,"speaker":"新美保健高齢事業部長","text":"それでは、私のほうから保健高齢事業部関係の幹部職員を紹介させていただきます。\n私、保健高齢事業部長の新美でございます。どうぞよろしくお願い申し上げます。\nそれでは、各課でございますが、健康課長の田中清朗でございます。"},{"i":23,"speaker":"田中健康課長","text":"田中でございます。よろしくお願いいたします。"},{"i":24,"speaker":"新美保健高齢事業部長","text":"それから、高齢福祉課長の早津一彦でございます。"},{"i":25,"speaker":"早津高齢福祉課長","text":"早津でございます。よろしくお願いいたします。"},{"i":26,"speaker":"新美保健高齢事業部長","text":"それから、介護保険担当課長の高橋純子でございます。"},{"i":27,"speaker":"高橋介護保険担当課長","text":"高橋でございます。よろしくお願いいたします。"},{"i":28,"speaker":"新美保健高齢事業部長","text":"高齢事業課長、蓼沼三郎でございます。"},{"i":29,"speaker":"蓼沼高齢事業課長","text":"蓼沼でございます。よろしくお願いいたします。"},{"i":30,"speaker":"新美保健高齢事業部長","text":"それから、社会福祉協議会へ派遣で、品川介護福祉専門学校の事務長をしております山岡豊治でございます。"},{"i":31,"speaker":"山岡保健高齢事業部副参事","text":"山岡でございます。どうぞよろしくお願いいたします。"},{"i":32,"speaker":"新美保健高齢事業部長","text":"保健高齢事業部は以上でございます。"},{"i":33,"speaker":"青山品川区保健所長","text":"保健所長の青山でございます。よろしくお願いいたします。\nそれでは、私のほうから保健所の幹部職員を紹介させていただきます。\n島袋衛生課長でございます。"},{"i":34,"speaker":"島袋品川区保健所衛生課長","text":"島袋でございます。よろしくお願いいたします。"},{"i":35,"speaker":"青山品川区保健所長","text":"寺西保健サービス課長でございます。"},{"i":36,"speaker":"寺西品川区保健所保健サービス課長","text":"寺西でございます。よろしくお願いいたします。"},{"i":37,"speaker":"青山品川区保健所長","text":"よろしくお願いいたします。"},{"i":38,"speaker":"河野品川区保健センター所長","text":"それでは、保健センターの幹部職員を紹介いたします。\n私は、保健センター所長の河野でございます。どうぞよろしくお願いいたします。\nまず、保健センターの衛生課長の高橋でございます。"},{"i":39,"speaker":"高橋品川区保健センター衛生課長","text":"高橋でございます。よろしくお願いいたします。"},{"i":40,"speaker":"河野品川区保健センター所長","text":"それから、保健センターの保健サービス課長、小林でございます。"},{"i":41,"speaker":"小林品川区保健センター保健サービス課長","text":"小林でございます。よろしくお願いいたします。"},{"i":42,"speaker":"河野品川区保健センター所長","text":"それから、大井保健相談所長の伊藤でございます。"},{"i":43,"speaker":"伊藤大井保健相談所長","text":"伊藤でございます。よろしくお願いいたします。"},{"i":44,"speaker":"河野品川区保健センター所長","text":"以上、４名でございます。よろしくお願いいたします。"},{"i":45,"speaker":"塚本委員長","text":"よろしくどうぞ。\nそれから、この１年間厚生委員会の事務方を務めていただきます事務局員をご紹介いたします。\n伊藤書記でございます。"},{"i":46,"speaker":"伊藤書記","text":"よろしくお願いいたします。"},{"i":47,"speaker":"塚本委員長","text":"それから、中村書記でございます。"},{"i":48,"speaker":"中村書記","text":"よろしくお願いいたします。"},{"i":49,"speaker":"塚本委員長","text":"どうぞよろしくお願いいたします。\n────────────────────────────────────────────\n２．事務事業概要"},{"i":50,"speaker":"塚本委員長","text":"それでは次第の２、事務事業概要の説明に入ります。\n進め方につきましては、説明質疑ともに事業部ごとに一括して行いたいと思います。\nなお、事務事業概要につきましては、改選後初めての委員会で、各所管の事務事業概要について説明を受けるものであります。したがって、具体的な質疑は今後報告事項の案件が出ましたら、その中で詳しく展開をしていっていただきたいと思いますので、ご留意ください。\nそれでは初めに、福祉事業部から入ります。"},{"i":51,"speaker":"小沼福祉事業部長","text":"それでは、私のほうから福祉事業部関係の総括といいますか、概要につきまして述べさせていただければと思います。\n恐れ入りますが、今席上に配付させていただいておりますけれども、「平成１５年度品川区の福祉ダイジェスト版」というものが配られていると思いますが、それの５ページをちょっとお開きいただければと思います。\n概括の関係でございますので、組織、その関係での人員というものを中心としまして、私のほうから少しご案内しておきたいと思います。\nまず、福祉事業部につきましては、行政組織としましては、１部４課の構成でございます。障害者福祉課、それから生活福祉課、児童課、保育課ということで、事業部門といたしましては、障害者福祉部門、生活福祉部門、これは生活保護を中心としてのことになります。それから児童福祉の部門ということで、高齢者福祉を除きまして、押し並べて福祉の関係につきましては、私どものほうで管轄している組織でございます。\nなお、人員でございますが、福祉事業部につきましては、これは今年の４月１日現在ですが、９８９名ということで、全職員のおおむね３分の１を抱えている、大変大きな事業部というのが一つの組織的な特徴でございます。それぞれの内容につきましては、この後、所管の課長のほうからるるご案内させていただけると思います。\n概括につきましては、私のほうからは以上でございます。"},{"i":52,"speaker":"塚本委員長","text":"続いて願います。"},{"i":53,"speaker":"日下部障害者福祉課長","text":"それでは、私のほうから障害者福祉課の事務事業のあらましについて、ご説明をさせていただきたいというふうに思います。\nただいまお開きいただいております５ページをご覧いただきたいというふうに思います。\nこちらの一番上段にございます障害者福祉課につきましては、庶務係から心身障害者福祉会館まで、全部で７係の体制で障害者福祉を中心としまして、事務の執行に当たっているという状況でございます。\nそれから、９ページをお開きいただきたいというふうに思います。\nまず、「心身障害者（児）の福祉」ということで、障害者を取り巻く状況について、特徴的なことについて、簡単にご説明をさせていただきます。\nこちらの前文にございますように、このところ、障害者の数は増加傾向にあります。交通事故、それから脳血管障害ということで、中途障害者の方あるいは高齢の障害者の方が特に増えているという状況でございます。それから、障害の種類や程度、これが重度化、長期化している。さらに、障害者自身や介護者の方の高齢化も進んでいるということでございます。\nこうした中で、中段にございますように、本年度から新しいサービス提供の仕組みであります支援費制度が導入されました。このような状況の変化を踏まえまして、区といたしましては、障害者福祉のなお一層の充実に取り組んでいくということで考えてございます。\n次に、各事業のあらましの説明でございますけれども、項目が非常に多岐にわたりますので、主なものに絞りましてご説明をさせていただきたいというふうに思います。\nそこで、まず１点目の「支援費制度」でございます。このポイントでございますが、介護保険制度と違いまして、契約制度とはいうものの、従来の公費負担、この仕組みは基本的には変わっておりません。そこで、(1)にございます対象となるサービスでございますけれども、これはこちらの一覧をご覧いただきたいと思いますが、身体障害者、知的障害者、それから１８歳未満の障害児ということで、居宅サービス、施設サービス、これだけのメニューが支援費制度の対象になってございます。\nそれから、(2)にあります手続であります。これにつきましては、１０ページをお開きいただきたいと思います。この流れ図ということで、区と利用者と事業者の三角の関係は変わりません。ただ、区のほうから支給決定を受けまして、一番大きなところは利用者と事業者、この間で3)の契約ということで、今までは区から事業者に委託をするということでサービスを提供しておりましたが、この支援費制度では、利用者と事業者との間で契約を結ぶ、これがスタートになります。それから、大きな違いとしましては、利用者の負担額の支払いが今までは区でありましたけれども、これを指定事業者のほうに直接支払っていただく、このようなことで、手続も変わってくるというものでございます。\nそれから続きまして１０ページ、２の「手帳の交付」でございます。障害者の方がさまざまな援護を受けるための基本となるものでございまして、下のほうに身体障害者とありますが、「身体障害者の手帳」をお持ちの方は、平成１５年４月１日現在で約７,５００名でございます。それから、(2)に「愛の手帳」とあります。これは知的障害者の方のための手帳ですけれども、これが１,２００名ということで、合計約８,７００名の方が手帳の交付を受けていらっしゃるということでございます。\nそれからちょっと先にまいりまして、１２ページの下のほうにまいります。「施設入所」とありますけれども、身体と知的ということで、それぞれの障害の状況に応じて区内、それから区外の施設に入所、通所をされているという状況でございまして、大体あわせて５４０人ほどの方が施設を利用していらっしゃいます。\nそれからちょっと先にまいります。１５ページでございます。(6)「品川区の障害者生活支援センター」、これは障害者の方が在宅での生活を幅広く支援しようということで、昨年の９月に開設をいたしまして、こちらにありますようないろいろな相談をはじめとして事業を行っております。\nそれから、(7)「品川区の障害者就労支援センター」、これは本日、後ほど報告事項で詳しくご報告をさせていただきますが、障害者の就労支援ということで、新しく事業を開始してございます。\nそれから１６ページにまいります。５の「障害者の福祉手当」ということで、説明は省略させていただきますけれども、国の制度、これが１６ページにございます。\nそれから、東京都の独自の制度が１７ページにございます、「重度心身障害者手当」。それから区の手当の制度、「心身障害者福祉手当」ということで、これも重度対象の方の二種、それから中軽度、難病を中心としました二種ということで、手当の支給をしてございます。\nそれから２０ページにまいります。６の「日常生活の支援」ということで、いろいろと幅広くきめ細かなサービスを提供してございます。これも非常に内容が細かいんですけれども、２１ページにまいります。(5)日常生活用具の給付と貸与ということで、２２ページ上段に一覧表がございます。細かいものはその他でくくっておりますけれども、こちらにもありますように、かなりいろいろな種類の日常生活にかかわる用具を給付させていただいております。\nそれから２２ページの(6)「補装具の交付・修理」でございますけれども、これも２３ページに一覧表があります。障害に応じまして、さまざまな補装具を交付させていただいているという状況でございます。\n一番多いのは、この一覧表をご覧いただきましてもおわかりいただけると思います。ストマ用の装具ということで、人工肛門の関係ですね、内部障害の関係で、このストマの交付が大変増えております。\nそれから２３ページ、下のほうにまいりますが、(7)の「住宅設備改善費の助成」ということで、障害者の在宅生活をバックアップするということで住宅改修を進めておりますが、２４ページに一覧表がございます。実は、この住宅設備の改善につきましては、一番上段にありますとおり昨年の７月１日に制度の改定をいたしまして、種目を大くくりにしまして大変使いやすくなってございます。\n続きまして、２８ページにまいります。下のほうの７、「社会参加への支援」でございます。障害者の方の自立と社会参加をバックアップするということで、いろいろな取り組みをしております。(1)「福祉タクシー利用券の交付」、これは懸案になっておりましたが、今年度分から対象者の方には、郵送させていただいております。\nそれから、３０ページにございます「リフト・寝台付福祉タクシー」ということで、タクシー会社と契約をしまして、５台を常時運行して、フルに活用していただいております。\nそれから３３ページにまいります。８に「障害者の介護」とあります。障害者の方が在宅で自立した生活を営めるようにということで、ホームヘルパーの派遣等を行っております。３３ページは家事援助介護サービスです。そのほか、いろいろな種類がございます。\nそれから３４ページの中段、(3)「障害者の緊急一時保護」ということで、介護者の方がいろいろな理由で介護ができなくなったという場合に、この下のほうに保護の形態とあります。短期入所（ショートステイ）をはじめとしまして、これはほかの区にはあまりありませんけれども、さまざまなサポートの体制を用意してございます。\nそれから先にまいりまして、３９ページをお開きいただきたいと思います。「心身障害者団体」ということで、実は、今まで７団体ということでまいりましたけれども、実は一番下から３行目に「品川区の傷痍軍人会」とあります。ただ、こちらの会につきましては、高齢化が大分進みました。それから、死亡等によりまして、会員数もどんどん毎年少なくなってくるという状況の中で、実は４月１３日付で解散をしたいということで届出をいただいたという状況でございます。\nそれから、４０ページにまいります。１１番の「民生委員」です。障害者福祉課としましては、いろいろな事業、障害者分野以外にも行っております。この民生委員の活動の窓口にもなっております。この民生委員活動は、住民に最も身近な相談相手ということで、地域福祉の大変重要な担い手としての役割を行っていただいております。そこで、区のほうといたしましては、民生委員活動をはじめとして、今後の地域福祉を推進するための指針といたしまして、このたび品川区の地域福祉計画、これを策定いたしました。現在わかりやすいパンフレットも作成しておりますので、次回の、今月末に開催されます委員会のほうで、この内容について詳しくご報告をさせていただきたいというふうに思っております。\nそれから先にまいります。４９ページでございます。「心身障害者福祉会館」です。こちらにつきましては、昭和５２年に開設をされまして、２５年、既に四半世紀が経過をいたしました。障害者の自立と社会参加の拠点ということで、この２にございます「在宅障害者へのデイサービス」ということで、さまざまな幅広い事業を展開しております。\nそれから、５１ページにまいります。４番目に「心身障害者の通所訓練事業」ということで、現在５０名弱の方の身体障害者、知的障害者の方が毎日通所でご利用いただいているという状況でございます。ただ、冒頭述べましたように、障害者をめぐる状況というのは大変大きく変化をしております。本年度からは新しい支援費制度もスタートしたということで、今後の会館のあり方について、現在検討を進めてございますので、次回の委員会でその辺の内容についてもご報告をさせていただきたいというふうに考えております。\n以上が障害者福祉課の事務事業のあらましでございます。"},{"i":54,"speaker":"黒田生活福祉課長","text":"では、私のほうから生活福祉課の事務事業ということで、５ページをお開きください。\n生活福祉課は、保護事務係から保護第四係まで、６係で構成してございます。保護事務係が相談窓口ということで、唯一の窓口になってございます。あと、保護の第一係と第四係がそれぞれの地域にわたる個別援護ということで関わってございます。\n次に、１００ページをお開きください。「高額療養費等支払費用の貸付」ということでございますが、疾病等の療養のため多額の医療費が必要になった場合に、その支払いが困難な人に対し資金を貸し付けることにより、区民の療養を確保し、生活の安定を図れるよう援助を行うものでございますが、この高額療養費につきましては、本年度より基金から一般会計に変わってございます。予算が１億６,３００万円余ということになってございます。\n次、１０２ページをお開きください。「その他の事業」として、「行旅病人および行旅死亡人の取扱い」を行ってございまして、そのほかに墓地埋葬法に関する法律に基づく事業ということで行ってございます。\n次に１０３ページ、社会保障制度の根幹をなしている生活保護制度でございます。\n「生活保護」ですが、憲法第２５条に規定する生存権の保障を具現化するもので、生活に困窮する者に対し、その者の資力と需要を調査した上で、その必要に応じて経済給付を行うものでございます。生活保護の基本原理でございますが、四つということで、第１条から第４条となってございます。保護の種類でございますが、性格により８種類ということで、生活扶助から葬祭扶助まで八つの扶助がございます。\n１０４ページ、「保護の決定方法」、次の４が「保護基準」でございますが、この保護基準は保護を必要とする者の年齢別、世帯構成別、所在地別などに分けて厚生労働大臣が毎年定めているもので、最低生活の構成要素として、最も中心的なものが生活費にかかる生活扶助ということで載せてございます。\nこの基準額ですが、生活保護制度が始まってから、毎年積み上げられてきたものですが、平成１２年の４月１日からは改定が３年間据え置かれて、今年度、この４月からはこの制度が開始してから初めて０.９％引き下げが行われました。ということでございます。\n次、１０５ページでございます。「保護の方法」ということで、原則として自宅で保護する居宅保護と、必要なとき、本人の希望により施設に入所させて保護を行います。\n続きまして、「品川区の現況」でございますが、各年度平均ということで載せてございますが、平成１４年度の平均は、被保護世帯が２,８６６世帯、被保護人員が３,４６８人ということで、保護率が１０.７パーミルとなってございます。ちなみに、平成１５年の３月末現在では、被保護世帯が２,９５２世帯、被保護人員が３,５７７人となってございます。\n１０７ページですが、「法外援護」とございます。被保護世帯に対し、生活保護法で最低生活を保障しているが、さらに生活の向上と自力更生への意欲を助長するため、法外で援護を実施しているものでございます。ということで、区見舞金の支給から、修学旅行支度金の支給、それと生活保護受給者の生活支援訪問家事援助ということで載せてございます。\n以上、雑駁でございますが、終わらせていただきます。"},{"i":55,"speaker":"辻田児童課長","text":"私からは、児童課の事務事業概要をご説明いたします。\n初めに、５ページをお開きください。児童課は３係１担当主査ということで、そのほか児童センターを所管しているということでございます。\n児童センター改革担当主査は、本年４月に新設されました。少子化の進行や社会状況の大きな変化により、子どもや子育て家庭を取り巻く大きな変化に対応するため、児童センターの役割を地域の子育て支援の拠点としてきめ細かな支援ができるように見直すために設置されたというものでございます。\nそれから、児童課の所管の基本的な考え方でございますが、保育事業以外の子育て支援につきましては、児童課が担っていくということです。ひとり親家庭に対する対応であるとか、母子支援施設のひまわり荘、これらも所管しており、福祉事務所的な役割も果たしているということでございます。\n次に、５４ページをお開きください。ここに児童福祉施策の考え方が示されております。この中で、核家族の問題であるとか、それから地域の子育て力の低下などが単に特定の家庭に及ぼす影響ということじゃなくて、すべての家庭に何らかの影響を及ぼしているということをここでるる述べて、そしてそれに対する施策を今後展開していくということがここに書かれてございます。\nそれから次、５５ページでございます。児童福祉のさまざまな課題を検討する区長の諮問機関として、「区児童福祉問題調査会」を担当しております。現在、３月１８日に諮問を受けました。「中・高生の自立した活動の拡大と地域のかかわりについて」ということで、中・高生問題に果敢に取り組んでいるということでございます。\n次に、６０ページをお開きください。ここでは、「子どもをめぐる各種相談事業」を実施しております。中心的施設である昨年９月に開設いたしました区立家庭あんしんセンター、こちらで子育ての一般相談や発達、療育相談など幅広い相談を受けております。また、インターネットを活用しまして、２４時間の相談も受けるというような体制をとっております。\nまた、そのほかは、各地にあります児童センター、保育園などでも相談を受けているということで、相談体制の充実を図っているところでございます。\n次に、６６ページをお開きいただきたいと思います。ここには、先ほどちょっと説明いたしました「子育て支援事業」として、区立家庭あんしんセンター内のひまわり荘以外の子育て事業、支援事業が書かれております。\n運営は福栄会のほうに委託しておりまして、子育て支援センター事業として先ほど説明いたしました相談業務、ほかに子どもの家庭在宅サービスとしてショートステイ、トワイライトステイ事業をスタートさせております。また、児童虐待防止協議会を本年１月に発足させ、現在関係機関と連携をとり、発生の防止に取り組んでいるところでございます。事務局を家庭安心センターに置いております。さらに、地域の子育て力が低下する中、地域の中で子育てを支え合う仕組みづくり、ファミリー・サポート事業、これをここで取り組んでいるところでございます。提供会員、また、依頼会員でこの事業はできておりますけど、その確保もだんだんと順調に進んでいるということでございます。\n次に、７７ページをお開きください。ここでは「児童センター」の業務が書かれております。児童の健全育成のため、遊びの場と機会を提供し、自立の援助をしているということでございます。また、子育て家庭への支援のための相談、幼児クラブの充実であるとか、親子サロンの設置などを進めているところでございます。さらに、昨年、平成１４年からはティーンズプラザを設置し、中・高生の居場所づくりなどに積極的に取り組んでいるところでございます。\nそれから次に、８３ページから８７ページ、国や区が行う「児童の各種の手当」でございます。子育てに伴う経済的負担を軽減するため、国の制度である児童手当、それから母子家庭、ひとり親家庭へ支給する区の事業である児童育成手当、また特に中心的に母子家庭への経済支援としての国の制度である児童扶養手当などを実施しているところでございます。\n次に、８８ページをお開きください。ここでは、「乳幼児医療費助成事業」であります。就学前の乳幼児を対象に、保険診療の自己負担分などを、所得制限を設けて助成しております。今年度４月からは所得制限を緩和し、およそ９０％の乳幼児がいる世帯に対して助成できるように制度を改正しているところでございます。\nその次のページ、８９ページでございます。ここからは「母子・女性、低所得者の福祉」ということで、母子および寡婦福祉法に基づきまして、母子相談、それから福祉貸付金などを行っております。そのあと、貸付状況とか、貸付の一覧表が書かれております。\n次でございます。９３ページ、ここは母子支援施設の「ひまわり荘」でございます。先ほど説明いたしました区立家庭安心センターの中にございます。児童福祉法に基づき、配偶者のない母親と扶養されている児童を保護するとともに、自立の促進のため、生活を支援するという施設でございます。\nそれから次のページ、９４ページでございます。この中ほどに「女性福祉」とございます。女性福祉の向上と自立促進のために相談や女性福祉資金の貸付などの事業を行っております。平成１３年度からは配偶者からの暴力の防止および被害者の保護に関する法律、いわゆるＤＶ法が施行されまして、関係課と連携をとり対応しているところでございます。ここでは、そういうような事業を行っているところでございます。\n次に、９７ページでございます。ここでは、主に「家庭福祉」ということで、一般的な家庭相談を扱っております。家庭内で発生するさまざまなトラブルに対して、家庭相談員を置いて調整の仕方であるとか、問題解決の方法について、相談を受けているところでございます。\nそれから次のページ、９８ページでございます。ここからは、「ひとり親家庭福祉事業」ということで、「休養ホーム事業」や、それから「緊急一時介護人派遣事業」、それから「ひとり親家庭の医療費助成」、また次のページには、「ひとり親家庭等居住安定支援事業」ということを行っております。\nそれから最後でございます。その次、１０１ページでございます。中段に、「入院助産」という事業がございます。児童福祉法の母子の保護という観点から、この入院助産、入院して分娩する必要があるにもかかわらず、経済的な理由によって、その費用を支払うことが困難な妊産婦を助産施設に入院させて助産を行っているということで、これは児童課の所管になっているということでございます。\n大変雑駁でございますが、私からは以上でございます。"},{"i":56,"speaker":"金子保育課長","text":"それでは、私から保育課の事務事業のあらましについてご説明申し上げます。\n５ページのところにまずお戻りいただきたいと思います。\n５ページの一番下、福祉事業部の一番下ですが、保育課では保育計画係、運営係、栄養担当主査、入園相談係と保育園で構成して、事業を実施しているところでございます。\n今年度、栄養担当主査を新設しております。従来運営係の中にありました栄養士６人を保育園の給食を中心に特化して組織を整備したものでございます。\n飛びまして６７ページのところをお開きいただきたいと思います。\n６７ページのところから、私どもの事業のご説明を載せてあります。\nまず、「保育園」でございますが、保育園は児童福祉法に基づきまして保護者が労働あるいは疾病などのために乳幼児の保育ができないとき、保護者にかわって保育をし、児童の発達と保護者の就労を支援する、こういうための施設でございます。\n現在は、公立が学務課所管の二葉つぼみ保育園を含めまして３８園、私立が８園、計４６園で保育の事業を実施しております。最近では、区民の保育の要望も非常に多様化しておりますので、私どもとしてはさまざまな特別保育事業を実施しております。\n上から３分の１あたりからありますとおり、一番大きなものが「延長・夜間保育」でございます。私どもの保育園は、基本の保育時間を午前７時３０分から午後６時３０分までの１１時間というふうに設定しておりまして、この中で午後８時３０分までの夜間保育園が真ん中あたりにありますとおり、公立では北品川保育園をはじめ４園、私立では緑の家をはじめ３園、計７園としております。午後１０時までの夜間保育につきましては、公立で７園、私立で１園ということで、８園で実施しております。ちなみに、現在８時半までの西大井保育園につきましては、再開発ビルの竣工によりまして、来月移転しまして、９月からは１０時までの夜間保育に変更する予定にしております。その他の園につきましては、１時間延長しまして、すべて午後７時半まで延長保育を実施しております。\n次に、「休日保育」でございます。休日に保護者が就労のため保育できない場合に、区立の中延保育園、大井保育園の二つの園でお預かりしております。\nそれから、「病後児保育」です。こちらは保育園、幼稚園に通園しているお子さんが、病気の回復期で集団保育が困難である場合に、公立では西五反田保育園、清水台保育園、私立ではどんぐり保育園の１園、計３園でお預かりしております。先ほど申し上げました西大井保育園では、９月から休日保育ならびに病後児保育を実施する予定としております。このほか、年末保育を実施しておりますが、１２月２９日から３１日のうち２日から３日、実施園は１０園前後で、年によって違いますが、毎年定めて実施しているところでございます。\n次に、「給食」です。給食につきましては、乳幼児の体の基礎をつくる、あるいは食生活の習慣をつくる等々の意義と役割を考えまして、保育園において昼食とおやつ、また延長・夜間保育では、必要に応じて補食、夕食を提供しているところでございます。ご案内のとおり、調理代行につきましては、平成１２年度から導入しまして、今年度で２９園の実施となってございます。予定としましては、来年度９園が実施をして、全園が調理代行となるというふうに考えております。\n次に６８ページをお開きいただきたいと思います。「ふれあい給食」です。この事業は、世帯間交流の一環として、高齢者を保育園にお招きして、高齢者と園児がともに給食を通してコミュニケーションを図る、こういう事業でございます。\n次に、「ふれあいデイホーム事業」です。この事業は、在宅福祉の実施と、保育園の人材等を有効活用する事業として始めまして、保育園が運営する高齢者の通所施設というものでございます。現在は、八ツ山保育園、五反田保育園の２園で実施しております。\n次に飛びまして、７４ページをお開きいただきたいと思います。７４ページの中ほどに、(2)の「保育室運営助成」というものがございます。これはいわゆる認可外保育施設のうち、都と区で助成しているもので、これにつきましては、昨年度の年度当初は４園を対象としておりましたが、現在では２園になっております。他の２園は次の認証保育所のほうに現在では移行しております。\nそれで３番の「認証保育所」です。これは一昨年東京都が創設した制度で、Ａ型とＢ型がございます。Ａ型につきましては、駅から徒歩５分以内の施設が中心ということで、駅近隣型施設として新設されるものを対象としております。Ｂ型につきましては、今ご説明申し上げました保育室をレベルアップして移行するというふうな考え方を東京都では持っております。品川区におきましては、Ａ型については目黒駅近くの旧予防研跡地の公団住宅のところ１カ所と、目黒線の不動前駅に１カ所の計２カ所となっております。Ｂ型につきましては、先ほどの保育室として助成しておりました品川学童園、それからめだか保育園が対象としております。Ａ型につきましては、このほか、他区にあります施設に通っていらっしゃる品川区民の方についても助成しております。Ｂ型につきましては、先ほどの保育室の残り２園がございますが、こちらの２園がＢ型のほうに移行したいというふうな希望を持っているということで、現在調整準備中でございます。\nそれから、「緊急一時保育の制度」ですが、次の７５ページになります。一時保育につきましては、二本立てで実施しておりまして、７５ページの緊急一時保育、これは奉仕員２名の方にお願いしているもので、もう一つが、次の７６ページの中ほどになりますが、保育園で各園２名の定員でお預かりする、こういう二本立てで実施しているものでございます。\n以上簡単ですが、保育課の事務事業のご説明を申し上げました。"},{"i":57,"speaker":"中川原福祉事業部副参事","text":"では、私のほうから品川介護福祉専門学校を除きました「社会福祉協議会」の説明をさせていただきます。１１０ページをお開きください。\n社会福祉協議会は社会福祉法に基づいて設立されまして、区の財政的、自立的な支援のもと、市民参加による地域福祉の中心的な推進役としてその役割を果たすことを期待されている団体です。昨年、設立５０周年を迎えまして、改めて支え合いのホットコミュニティという新しい理念をつくり、さらに品川区地域福祉計画の中で地域福祉の担い手として改めて果たすべき役割を確認いたしました。\n今年度の運営につきましては、１１０ページの図のとおり、事務局次長と成年後見センター所長のもと、五つのセクションという編成で運営してまいります。\n次に１１１ページをお開きいただきまして、「各種福祉事業」につきましてですが、これは庶務係が担当しているんですが、特に各種福祉事業の下から二つ目でございます居宅介護事業ですが、この４月から支援費制度の導入に伴いまして、新規事業として行うものでございます。\n次に１１１ページの下、「ボランティアセンターの事業」でございますが、ボランティアの登録、受給調整を中心に行ってまいりましたが、１１８ページ以降にもございますように、ふれあいサポート活動の推進をはじめとする地域でのボランティア活動の活性化のために、今後さらに情報提供や地域センター職員等のコーディネート力の向上のための研修、また必要な調整の支援等を積極的に行ってまいります。\n次に１１３ページの「さわやかサービス」でございますが、これは区民のボランティア精神に基づく相互援助による有償在宅福祉サービスです。高齢者等の自立した生活を継続できるよう家事援助、移送サービスを中心とした活動を行っています。地域の支え合いとして、プロのサービスとは一味違う家族的な温かみのあるサービスとしての魅力をさらにアップしていく予定です。\n１１４ページをお開きください。１１４ページは「ふれあい作業所」でございます。ふれあい作業所は、知的障害者の授産施設です。区立公園５８カ所の清掃事業や自主製品の作成・販売、放置自転車のリサイクルなどに取り組んでおります。\n次に１１４ページの下、福祉ショップ「テルベ」ですが、これもイトーヨーカドーの協力で区内をはじめとする城南５地区の福祉施設、２８カ所の授産製品の販売を行っております。\n次に飛びまして１１６ページをご覧ください。１１６ページ以降は、「成年後見センター」でございます。昨年６月に開設しまして、平成１２年度から検討してまいりました品川区の権利擁護の仕組みについての検証を行いながら、去年１年、実際の相談やモデル事例による検証を行いながら、最終報告書をまとめたところでございます。今年度は本格稼動ということで、利用者の実態に合った柔軟な制度運営を行えるようさらに充実を図ってまいります。"},{"i":58,"speaker":"塚本委員長","text":"以上で、福祉事業部の説明が終わりました。ご質疑を承ります。\n大変多岐にわたった話でございますので、また、当委員会には一期生、初めて議会を体験する方も３名いらっしゃいます。どうぞここはと思うところのご質問をいただきまして、また後ほどの報告事項や１年かけて調査していく中で、いろいろなことも理解が深まるかと思いますけれど、入口のところでぜひとも確認しておきたいというところがございましたら、ご発言を願いたいと思います。"},{"i":59,"speaker":"須藤委員","text":"ちょっと１点だけ確認なんですけど。二、三日前、新聞で未就学児の教育と福祉のところで、国のほうでドッキングしていきますよというようなお話がちょっとあったんだけども、今品川区ではその辺をどんどん進めてきていると思うんだけど、今後の方向性はどうなりますかね。今、児童課、保育課と分けていますよね。その辺はどういうふうになるのか、もしそうなってきた場合に、うちではどういうふうな考え方をつくっていけばいいのか。"},{"i":60,"speaker":"金子保育課長","text":"委員ご指摘のとおり、たしか今日の新聞でも保育と教育の就学前の子どもに対する施設を政府が検討しているというふうなニュースもありましたとおり、私どもでは、今年度予算でプリスクール西五反田というものの建設を計画しているということを既にご案内のとおりでございますが、昨年度、幼保一元化事業として二葉幼稚園の中に、二葉つぼみ保育園というものを設置して、一つの形で実践しているところでございますが、現在、今申しましたプリスクール西五反田を検討しているところですが、これの中でも、保育と教育という二つの分野を融合させて、今までのそういう象徴的な縦割あるいは法制度としての縦割の部分を超えて、就学前の教育ということで一貫したものを組み立てて実践していこうと現在検討しているところでございます。組織につきましても、現在あわせて検討しているところでございますので、もう少しお時間をいただければというふうに考えております。"},{"i":61,"speaker":"鈴木（ひ）委員","text":"９ページなんですけど。支援費制度が始まりました。そして支援費の対象となるサービスというふうなことで、居宅サービス、施設サービスというふうなことで書かれていますけど、ここは品川区の施設が、この中の、例えば更生施設であれば、何と何というふうなのがわかるような一覧表があるといいなというふうに思うんですが、ちょっといろいろと詳しく見ていけばわかるのかもしれないんですけれども、どれが支援費に当たって、そしてどれぐらいの支援費の対象のサービスが品川区でどうなっているのかというのが、わかりやすくしていただけたらなというふうに思うんですけども、いかがでしょうか。"},{"i":62,"speaker":"日下部障害者福祉課長","text":"それでは、支援費関係のお尋ねでございますけれども、実はこちらの「品川区の福祉のダイジェスト版」の一番後ろの１２０ページをご覧いただきたいと思います。１１９ページ、これは法人別、それから１２０ページにまいりますと、これが施設の身体あるいは知的で一応分類をしてございまして、この中でそれぞれの施設の性格についても表記をしてございます。ただ、確かに例えば更生とは何ぞや、授産とは何ぞや、その辺も含めまして、少しちょっとわかりづらい面もあろうかと思いますので、その辺につきましては、もう少しまた一工夫ということで考えていきたいというふうに思います。"},{"i":63,"speaker":"大西委員","text":"ふれあい給食というのが出ておりましたが、このふれあい給食は、どれぐらいのスパンで行われているんでしょうか。それとまた、高齢者に対する、ひとり暮らしとかの高齢者の配食サービス、これが現在週２回という形であると思いますが、ニーズ的には週２回では足りないところがあるんじゃないかというふうに思っているんですが、その辺のところの要望等はどういうふうになっていますでしょうか。"},{"i":64,"speaker":"金子保育課長","text":"まず前段のご質問の保育園におけるふれあい給食ですが、現在ではおおむね水曜日、大体週１回実施しているところがほとんどでございます。"},{"i":65,"speaker":"早津高齢福祉課長","text":"私どものほうでも触れることになっておりますけれども、高齢者に対する学校給食の配食サービスは、基本的に委員ご指摘のように週２回ということになってございます。これはその高齢者の状態等によりまして、そのほかに在宅サービスセンターからの配食サービス制度もございます。そちらとの併用というのは現在のところ行っていないわけですけれども、その方の身体状況に応じてどちらが適切か、あるいはご希望されるのはどちらであるかというような中で行っているところでございます。とはいいながらも、ふれあいサポート活動の中で、今後の学校給食の配食のあり方等についても検討されるものと思われますので、その辺の検討についても見守っていきたいというふうに考えてございます。"},{"i":66,"speaker":"塚本委員長","text":"ほかにございますか。\nないようでしたら、次の部へ移ります。\n保健高齢事業部、保健所、保健センターの事業概要を聴取いたします。"},{"i":67,"speaker":"新美保健高齢事業部長","text":"それでは、保健高齢事業部、さらに保健所、保健センターの事務事業を含めてご説明させていただきますが、資料としましては、２分冊になっておりまして、「保健編」というものと、「高齢者福祉編」と２分冊になっております。私のほうからは、「保健編」のほうの２ページをお開きください。全体の組織等について簡単にご説明をさせていただきたいと思います。\n保健高齢事業部関連といたしましては、この本庁内に健康課、高齢福祉課、高齢福祉課に介護保険担当課長を置き、さらに高齢事業課という３課体制で進めております。\nなお、事業部制を敷きました平成１３年度から保健所保健センターの業務につきましても、保健高齢事業部長が統括するというような形で運営をしているものでございます。\nそれでは、個々の所管については事務分掌等ありますので、お目通しをいただければと思います。\n８ページをご覧ください。それぞれの課の「職員の配置状況」でございます。健康課あるいは保健所、保健センターを含めまして、一般事務のほかに保健師、心理、栄養士、歯科衛生士等々、多様な専門職種の職員が配置され、業務を行っているところでございます。\nまた、９ページ、１０ページが、「保健所、保健センター、大井保健相談所」、それぞれ３所が管轄区域を定めまして、特に保健サービス事業を行っておりますので、その旨、この表でご覧いただけばと思います。\n簡単ですが、総括的な説明を私のほうからさせていただいて、あとはそれぞれ各課長のほうからご説明をさせていただきます。"},{"i":68,"speaker":"田中健康課長","text":"それでは、私のほうから事業部内、健康課、それから保健所、保健センターの衛生課、保健サービス課、大井保健相談所、いわゆる保健関係を一括してご説明をさせていただきたいと思います。\n今の「保健編」をご覧いただきたいと思います。もう一度２ページをちょっと触れさせていただきたいと思いますが、保健高齢事業部の係は庶務係から衛生試験所までを含めまして、このようになってございます。今年、精神障害者福祉施設準備担当、後で報告させていただきますけども、この係、主査を新設いたしました。それから、保健所、保健センターでございますが、衛生課がそれぞれ、保健サービス課がそれぞれ、大井保健相談所も係が保健事業係、保健担当と、これは両所の保健サービス課と内容的にはほとんど同じでございますが、１０ページのとおり地域を担当しております。\nそれでは、中身に触れさせていただきます。資料等々がかなりついておりますが、一番最初にちょっとお戻りいただいて１ページの「総説」というところで、大柄な保健の部分の基本的な動きをご説明させていただきたいと思いますが、ご存じのとおり、保健所機能といいますと、歴史的には感染症を中心にした、いわゆる社会的な疾病等から区民を守る、国民を守るというところから始まってきたわけなんですが、現在は感染症、今はＳＡＲＳで大変いろいろな動きが起こっておりますが、そういう形よりは、高血圧ですとか糖尿病、がんをはじめとしました生活習慣病と言われる、生活習慣による病気が増えているということでございまして、私どもの保健高齢事業部の高齢部という形でも関係しますが、お年寄りが増える中で、より元気でいただきたいということがございますので、そこに向けての健康づくりというのが大きなテーマになってきていますが、ここにつきましては、私どもも後ほど申し上げますが、健康づくりプラン品川というものをつくっております。\nそれから2)でございますけれども、これも保健所のプロパーな大事な業務でございますが、食品、それから環境関係の衛生監視業務がございます。\n3)番目、4)番目、いわゆる区民健診等々の問題、それから感染症の問題、難病の問題、精神障害の福祉サービスの問題、それから医療に関します、かかりつけ医、それから両医師会との関係ということを大まかにやってございます。\n概括は以上でございまして、ちょっとページを先へ進ませていただきます。\n事業という内容では、ちょっと総括的なところが多うございますので、３２ページをご覧いただきたいと思います。\n３２ページ以降が各課のそれぞれ具体的な業務でございますので、ここから少しお話をさせていただきたいと思います。\nまず、「環境衛生」、保健所、保健センターの衛生課が担当している部分でございます。環境衛生関係の営業施設の許認可および栄養指導ということで、環境衛生監視という専門職に基づきまして、理容所、美容所、クリーニング所、興行場、旅館業、公衆浴場等についての指導等を行っているところでございます。\n３３ページ以降は、この辺の調査の実施状況等がございます。\n３４ページ、プール、それから衛生教育、ビル管理の問題、３５ページ、専用井戸の調査、居住環境、これはハウスシック等でございますけれども、こういう部分を担当してございます。\n３６ページ、ネズミ、衛生害虫等の駆除ということで、薬剤散布等の業務を行ってございます。\nそれから３６ページ下で、公衆浴場の整備のための設備補助等の助成を行っているところでございます。\n３７ページ、「薬事衛生」でございまして、「医薬品販売業に対する許認可および監視指導」、これも結局そういう形で販売店等に対する調査指導を行っているところでございます。\nそれから下のほう、「有害物質を含有する家庭用品の試買検査」ということで、こういうことで問題のある家庭用品についても検査を行っております。\n３９ページでございます。「食品衛生」でございます。「食品衛生関係の施設数および許可・監視指導」。これもご存じの方が多いと思うんですが、開いていただきまして、４１ページ、４２ページに過去の許可・監視指導を行ってございます。\nそれから、(3)で「食中毒の発生状況」等々、昨年度はおかげさまで２件と少なく、これからも注意していきたいというふうに考えてございます。\n先へ進ませていただきまして、４４ページをお開きいただきたいと思います。\n４４ページ、「獣医衛生」ということで、狂犬病予防法等に基づく畜犬の登録、それから予防集合注射等々を行ってございます。\nそれから４４ページの下段、「飼い猫の去勢・不妊手術」ということで、野良猫の防止を助成費で行っているということでございます。いずれも品川区獣医師会等の協力を得ております。\n８が「医事衛生」。これは私ども地域の医療施設の衛生水準を確保するために、いろいろな届出の受理ですとか、指導監督の事務等を行って、経由事務が多うございますが、主に診療所の関係につきましては、区が関与している部分でございます。\n進ませていただきまして、４８ページをご覧いただきたいと思います。これは今最後に申し上げました医療関係で、私ども医師会、歯科医師会、それから柔道接骨師会の協力等を得まして、「休日診療、それから小児平日夜間の診療」を委託によって行っておるところでございます。品川区医師会、荏原医師会、品川歯科医師会、荏原歯科医師会等々、４８、４９、５０ページまで休日等々の診療体制を確保しているところでございます。\nそれから５１ページでございますが、「かかりつけ医制度」ということで、品川区と荏原両医師会に対しまして、かかりつけ医制度をお願いしてございます。今こういうことでかかりたいけれど、手軽に地元で近いところでという紹介が医師会等々のほうに寄せられた際に、この制度を使いまして紹介をしているものでございます。\n５２ページ以降、「生活習慣病予防」でございます。先ほども挙げました生活習慣病の予防に対するいろいろな取り組みでございます。\n５３ページ以降に具体的にございまして、まず(1)「健康診査」のうち、一番代表的なものは、４０歳以上の区民に対して行っている1)区民健康診査でございます。これにつきましては、生活習慣改善指導事業というものを平成１３年の末から始めてございます。\n次にお開きいただきまして５５ページ、女性の健康診査、こちらについては、勤務先等で受診機会のない１６歳以上４０歳未満の女性に関しまして、健康診査を行っております。それから、骨粗しょう症の予防ということで、予防相談事業も行ってございます。\n５６ページ中ほどでございますが、「各種がん検診」ということで、がんにつきましては、年々いろいろございますが、胃がん、それから５７ページの下のほう、子宮がん、それからお開きいただきまして５９ページ、乳がん検診、それから６０ページ、肺がん検診、６１ページ、大腸がん検診というふうに５種目のがんの検診を行っております。この中で、近年、平成１３年１０月からは乳がんにマンモコースというものを入れまして、なるべく早く結果がわかるようにということで好評いただいておりますので、６０ページの肺がんのほうにも昨年１０月から有料でございますが、ヘリカルＣＴコースを新たに始めております。\nそれから６２ページでございますが、「成人歯科検診」ということで、歯科のほうの検診の体制でございます。歯科につきましては、６２ページの下のほう、1)成人歯科健康診査、これは毎年６月から３月いっぱいまで行っておりますが、４０歳以上、５歳刻みで６０歳に達する区民の方に歯科医師会のほうに委託して行っております。\nそれから、昨年から始めましたので６３ページ、2)歯周疾患改善指導事業、これにつきましては、４０歳、５０歳の区民の方で成人歯科を受けられて、改善指導の必要があるという方については、３回の改善指導を行うという内容で始めさせていただいております。\n６５ページでございます、「健康づくり」。\n「区民健康づくりプラン品川」、今日、後で報告の中で申し上げますが、この３月に策定をさせていただいております。これによりまして、今後区民に対する健康づくりの実践をこれから私ども区民の方に呼びかけて進めさせていただきたいと思ってございます。推進体制につきましては、この６５ページの下の表にございますとおり、各地域センターごとに身近で取り組んでいただけるようにさせていただきたいと思っております。\n６６ページでございますが、今申し上げた地域センターごとというのは、実は従前から(2)という上のほうから３分の１ぐらいございますけども、「地域健康づくり推進委員事業」とございまして、１９６名の推進委員に、一応今までも活動を取り組んでいただいてまいりました。これをもっと充実させるという意味で、今回のプランの中に一応考え方を盛り込ませていただいております。\n６６ページ後半でございますが、「健康センターの運営」、品川健康センター、それから６７ページの下のほう、荏原健康センター、この二つの健康センターを民間事業者に委託して、いろいろヘルストレーニング等々をお願いできるようにしてございます。\n６８ページ以降、その他のメニューが、例えば健康指導者の育成ですとか、食生活改善ですとか、健康塾ですとか、健康学習ですとか、いろいろ取り組ませていただいております。\n健康学習も７０ページにいろいろ保健所、保健センターでやっているメニューがございますが、今後は地域において出張健康学習というふうな形で進められるように、現在調整をしております。\n７１ページ、「母子保健」でございます。母子保健は、母子保健法、児童福祉法、さっき児童課のほうから、子育て等々のお話がございましたが、保健所のほうは、一番最初の「母子手帳」の交付等の前後、いわゆる妊婦、それから乳幼児の段階を担当してございます。「妊産婦の保健」ということで、「母子健康手帳」の交付、妊婦検診、歯科検診等を行ってございます。\n７３ページをご覧いただきたいと思うんですが、(2)、下のほうでございますが、「乳幼児の保健」ということで、新生児から４カ月、６カ月、９カ月、１歳６カ月の健診というふうに健診を行って、元気なお子さんに育っていただけるようにいろいろやってございます。\nそのほか７４ページ、9)以降、9)、10)、11)等々は、歯のほうのいろんな事業も歯科医師会と連動して行ってございます。\nこの後はいろいろなデータを載せさせていただいております。\n８１ページでございますが、母子関係には、医療費の助成制度というのがございまして、医療費の公費負担ですとか、養育医療の関係の事業を行ってございます。\n先へ進ませていただきまして、８４ページでございます。現在ＳＡＲＳで私どももいろいろ頑張って取り組んでおりますが、ここに「感染症の予防」ということで、感染症法という法律に基づいた取り組みを従来から行ってございます。平成１０年度の発生状況が８６ページにございますが、今回は特にＳＡＲＳ問題が大きな問題で、いろいろ対処を国、東京都と連動して進めているところでございます。\nそれから８４ページ、(3)では、従前からの「エイズ予防対策」への取り組み、それから８５ページで(4)「性感染症の予防」に対する取り組みを行ってございます。\n８７ページをお開きいただきたいと思います。感染症と同じく、従来から大きなチェック体制を持ってきました「結核予防」でございます。現在でも品川区は、毎年１００名ほどの患者の発生が見られてございます。これからも油断なく結核予防をとございますが、まず健康診断、予防接種を行っているところでございます。それで、検診についても、結核感染の患者が発生した場合に、感染の危険の高い患者家族およびその関係者ということに対するところに検診の重点がということで現在は推移をしてございます。\nいろいろデータがございますが、９１ページにまいりまして、結核につきましては、医療費の助成、それから入所命令等のいろんな制度がございます。それから、(6)、下のほうでございますが、「結核検診」、これは１６歳以上の区民の方に検診を行っているところでございます。\n９３ページにいかせていただきたいと思います。「特殊疾病」という言葉を使っておりますが、俗に言う難病でございます。医療費の助成等いろんな支援策がございます。平成１５年４月１日現在、国庫補助対象は４６疾病、都の単独補助対象が２７疾病、ほかに特殊医療補助対象２疾病ということでございます。内訳は９４、９５ページ等でございます。\nそれで、９６ページには「訪問診療」ですとか、いろんな医療費助成ですとか、そういう関係を載せてございます。\n９７ページでございます。「精神保健福祉」、こちらにつきましては、従来から心の健康ということで、保健所、保健センター等で取り組んでいる内容、それから健康課のほうで福祉的内容を含めて従来から共同作業等の運営に支援をしてまいりました。\n９８ページをご覧いただきたいんですが、保健所、保健センター等で主に行ってございます事業、2)専門医による精神保健相談、それからいわゆるデイケアといっております社会参加の促進のための事業、家族相談会等を従来から行ってございます。\nそれから、９９ページでございますが、こちらについては精神障害者保健福祉手帳の認定状況ですとか、それから医療費の公費負担の内容を載せさせていただいてございます。\n１００ページでございますが、精神障害者の共同作業所等々の支援をさせていただいてございます。それから、作業所同様に中ほどでございますが、グループホームの運営を委託してございます。かもめ工房等運営委員会に委託をしてございます。\nそれから１０１ページでございますが、平成１４年度からいわゆるホームヘルプ事業、精神障害者の訪問介護事業を行ってございまして、現在１９名の方にご利用いただいております。\nなお、後ほど報告申し上げますが、精神障害者の通所授産施設、生活支援センターを平成１６年度に現在の大崎第一地域センターが移転した跡に開設をさせていただくこととしまして、法人の立ち上げ等を含みつつ、現在動いてございます。後ほど設立準備会のことについてご説明を申し上げたいと思います。\n１０２ページでございます。「公害補償」にまいります。公害補償は、公害健康被害の補償等に関する法律でございますが、以前、第一種地域として品川区も指定されてございましたが、昭和６３年にすべての地域が指定解除になりました。この関係で、現在認定患者は、推移は１０４ページにございますが、どんどん減ってきてございまして、１,９０４名の方が認定をされております。\nまず、１０３ページでございますが、認定された方には(2)の補償給付、こういう内容で、実は保健関係の予算というのはかなりの数字がこの部分を占めてございます。もともとがこの補償給付等に関する費用というのは、原因者負担の原則ということで、法律で１０２ページのとおり定められています。真ん中の「公害健康被害補償予防協会」というところから、国等からのお金を、区を通じて認定された方に医療費等の給付を行っているという流れでございます。\nそのほか、１０５ページ等でございますが、保健福祉事業ということで、成人ぜん息講演会ですとか、リハビリ教室ですとか、各種の予防事業を行ってございます。\nいろいろ相談事業ですとか、健康教室を行っておりまして、あともう一つが、公害に近い関係では、１０８ページをお開きいただきたいと思いますが、東京都が大気汚染の影響を受けると思われる健康被害につきまして、医療費を助成しております。１８歳未満の方に慢性気管支炎等の症状が見られる場合に、認定をして医療費の助成を行っているものでございます。平成１５年３月末現在で１,３５９名の方が認定をされております。\n１０９ページ以降は、衛生試験所の「検査業務」の関係でございます。衛生試験所につきましても、現在いろいろあり方の見直しを行っているところでございます。\n雑駁でございますが、以上でございます。"},{"i":69,"speaker":"早津高齢福祉課長","text":"それでは、高齢者関係の事務事業につきまして、もう一冊の「高齢者福祉編」というもので、高齢事業課長と分担してご説明をさせていただきたいと思います。\nまず、５ページをお開きいただきたいと思います。高齢者の基本になります「人口」でございます。そちらのところにありますように、平成１５年４月１日現在５万９,０００人を超えたということで、パーセントで言いまして１８.３％、５.５人に１人が高齢者ということでございます。高齢社会の指標というのは１４％ですが、１８.３％になっているということで、平成２２年には２２.５％を予測しているという状況でございます。\n２番の「施策の考え方」ですが、高齢者と一口に申しますけれども、その身体状況等から見て、一様ではない、多様であるというところに着目をいたしまして、品川区では三つの高齢者像を想定いたしまして、対応する施策について展開してまいったところでございます。お元気な高齢者には下の図にありますように、高齢者の社会参加プログラムを中心とした施策、少し弱った方、自立支援が必要な高齢者に対しては、ふれあいサポート活動を中心とした地域における協働活動、さらに要介護高齢者等に対しては、介護保険制度を中心としました在宅介護支援システムを中心に施策を展開してまいったところでございます。６ページにはそのようなことが記載してございます。\n７ページをお開きください。「介護保険の運営」でございます。高齢福祉課の主たる対象は要介護高齢者ということになるんですが、施策上の中核となる制度は、言うまでもなく介護保険制度でございます。その運営の目標を５行ほどいったところでございますが、心身が不自由になっても、住みなれた我が家での生活を送ることができる、在宅重視である。かつ、在宅生活が困難になった場合には、施設への入所の見通しが立つようにするというのが介護保険制度を運用するに当たっての品川区の基本の考え方でございます。\n状況でございますが、右側のページに保険料が記載してございます。第１段階から第５段階までの保険料、第２期、平成１５年度から第２期ということになりますが、保険料につきましては、第３段階は３,３００円、すべて第１期と同じということでございます。ちなみに、全国的には８割の自治体が値上げ、２３区では２０区が値上げという中での状況でございます。ちょっと数字を申し上げますと、全国の保険料の第１期の数字が２,９１１円、これが第２期においては３,２９３円、３８２円値上げ、１３％ほどの値上げという状況でございます。収納率については、平成１４年度９７.２％ということでございます。\n１ページお開きいただきまして、９ページでございます。給付費の状況でございますが、平成１３年度、それから、上の段で「決算」、それから「１４年度の予算」と、隣の「給付費実績（見込）」となっておりますのが、１４年度の決算の大体の見込額ということになってございます。執行率８９％で、１３年度の決算と対比いたしますと１１４％、１４％の増という伸びになってございます。\n１０ページからは、「施策の概要」についてになってございます。\n１番で、要介護高齢者のための事業ということでございます。最初に「介護保険で受けられるサービス」でございますが、以下３４ページまでが介護保険で受けられるサービスを記載してございます。そのうち、まず在宅サービスの中で、(1)の「在宅介護支援センター」でございます。身近な地域での高齢者の総合相談窓口という機能を持っておりまして、中段のあたりに、内容を５項目記載してございます。相談と必要なサービスの調整、以下ケアプランの作成に至るまでの主な５項目の内容でございます。実績につきましては、次のページに以下記載してございます。１４ページまででございます。\n１５ページをおめくりいただきまして、在宅サービスのうち、家庭を訪問してのサービスでございます。(1)、まず中核となります「ホームヘルプサービス」。このホームヘルプサービスについては、中段の内容のところに二つございます。生活援助型と身体介護型になっております。生活援助型といいますのが、第１期の介護保険の制度下では、家事援助と呼ばれていた掃除・洗濯・炊事というようなものでございますが、名称が生活援助というふうに変わり、ホームヘルプサービスもこの２類型に整理をされたわけでございます。右のページに、そのほか２４時間の訪問介護が記載してございます。\n１７ページ、１８ページでは、訪問サービスのそのほか、「訪問看護」「リハビリ」「入浴」「巡回入浴サービス」が記載されております。\n１９ページでございます。在宅サービスのうち、施設を利用してのサービスでございます。(1)にありますのが、通所サービス、在宅サービスセンターで行う一般的な「通所介護」について記載をし、右側のページにその実績を記載してございます。\n２１ページは保育園で行っております「ふれあいデイホーム事業」ということで、八ツ山保育園と五反田保育園、実施場所のところに記載をしてございますが、２カ所で行っております。\n右側には、デイサービスのうち、痴呆性高齢者に特化しましたデイサービス事業ということで、小山の家と月見橋の家についての状況が、次のページにおきまして実績の形で記載させていただいてございます。\n２４ページでございます。「通所リハビリテーション」、デイケアと言われているものですが、こちらにつきましては、ケアセンター南大井で行っております。さきにご報告申し上げましたように、通所リハビリは非常に人気もあり、効果も期待されるところですが、供給制約を受けている関係で、品川区といたしまして、８月から「身近でリハビリ」という名前をつけました身近なデイサービスセンターでのリハビリ拡充施策を実施していくというものでございます。\n(3)、同じページですが、「ショートステイ」の状況が記載してございます。\n２５ページでございます。在宅サービスに入るのですが、その他的な項目で、福祉用具や住宅改修ということで、(1)が「福祉用具の貸与」、下段へいきまして、「福祉用具購入」ということで、レンタルのなじむ物、なじまない物について、貸与と購入というような形で分かれてございます。\nページをめくっていただき２７ページですが、住宅改修につきまして、(3)が介護保険内の住宅改修の制度でございます。中段にあります(4)が介護保険外の住宅改修事業というものでございます。実績等について記載してございます。\n２９ページでございますが、ここから「施設サービス」でございます。(1)にありますのが、「特別養護老人ホーム」ということで、実績といたしまして、一番下を見ていただきますと、入所者の数が、これは３月３１日時点でございますが、８８４名ということでございます。\n３０ページが「老人保健施設」でございます。ケアセンター南大井におきまして、同様ですが、３月３１日時点では８９名の入所者数ということでございます。\n３１ページに保険者としての事業を、以降記載してございます。\nまず、「要介護認定」でございますが、中段にありますように、介護認定審査会におきまして、要介護認定を行っているところでございます。回数は２０２回ということで、ほとんど毎日のように開催をしている状況でございます。\n３２ページですが、「介護保険制度推進委員会」ということで、附属機関である介護保険制度推進委員会を昨年度６回開催いたしまして、新たな事業計画の作成等を行ったところでございます。\n下の段に(3)として、「介護サービス向上委員会」がございます。サービスの向上を目指しまして、よりよい介護サービスのシステムづくり、仕組みづくりを行っているところでございます。\n１ページめくっていただきまして、３３ページに平成１４年度のサービス向上委員会の実績が書いてございます。通所介護、短期入所について、サービス評価を行いました。いずれもご利用者からは９３％を超える満足だとのアンケート評価をいただいているところでございます。\n(4)が「権利擁護のしくみの運営」ということで、「成年後見センターへの助成事業」でございます。中段ですが、平成１４年度にモデル実施を行いまして、意思能力の弱った方に対する本人にかわる区長申し立てを４件行ったところでございます。\n３４ページでございます。「特別養護老人ホーム入所調整」でございます。中段にありますように、会議の内容として特別養護老人ホームへの申し込みを受けて、品川区では全国と異なりまして、入所の優先度を審査するというものであります。申込順では混乱が多かったために、厚生労働省が実はその方針を変更いたしました。既に品川区は当初からこの形を行って、入所調整をしているところでございます。\n「福祉カレッジ」につきましては、山岡保健高齢事業部副参事のほうからご説明を申し上げます。\n次のページ、３５ページから「介護保険以外の一般福祉サービス」を記載してございます。(1)は「在宅介護者の激励研修」ということで、内容のところにありますように、激励事業および研修事業ということ、それから、(2)の「家族介護者教室」というあたりが在宅のご家族を支援する事業でございます。\n３６ページに「在宅療養者の訪問歯科診療事業」の実績が記載してございます。\n３７ページ、「高齢者福祉手当支給」でございますが、記載してありますけれども、２番目の対象の最後にありますように、１４年度をもって１５年度に廃止するというものでございます。\n３８ページからが「ひとり暮らし等高齢者のための事業」ということで、まず、「安否確認事業」といたしまして、「緊急通報システム」、2)の火災安全システム、次のページへ行きまして、「自動消火装置」ならびに「高齢者福祉電話事業」というような事業を記載してございます。\n４１ページで、「ひとり暮らし高齢者等給食サービス」ということで、ボランティア給食、学校給食、夕食サービスというようなものを行ってございます。そこに記載のとおりの実績になっておりますが、一番最後の下のところにありますけれども、この事業の実施に当たっては、現在区民生活事業部の地域活動課が担当をしているというような形になってございます。\n４２ページ、「高齢者生活支援事業」ということで、介護認定を受けているほどではないけれども、少し弱っている方への事業として1)がホームヘルプの派遣事業でございます。2)として、下の段に車いすの貸与事業が実績とともに記載してございます。\n４３ページは、(4)ですが、「高齢者相談等事業」ということで、1)が高齢者相談員、これは民生委員の方に高齢者相談員にあわせてなっていただき、活動報告あるいはひとり暮らしの方への訪問活動等を行っていただいているというものでございます。さらに2)でございますが、年賀状・暑中見舞状の送付。それから右のページへ行きまして、3)の布団乾燥事業、それから４５ページへ行きまして、「養護老人ホーム入所措置」というようなことが記載してございます。\n４６ページからは高齢事業課になりまして、６０ページへ飛んでいただきたいと思います。\n「高齢者や障害者にやさしいまちづくり」でございます。(1)にあります「やさしいまちづくり計画推進事業」につきましては、取り組みの経過にありますように、昭和５３年に要綱を制定して、いち早く取り組みまして、平成１０年度から平成１４年度までに、ＪＲ「大井町駅・大崎駅・目黒駅」エレベーター、ならびに、東急「大崎広小路駅」のエレベーター整備助成を昨年行い、「やさしいまちガイドマップ」についても作成をしたところでございます。今、最終の作成中でございます。平成１５年度におきましては、荏原中延駅へのエレベーターを整備する予定でございます。\n１ページ飛びまして、６２ページでございます。「施設等基盤整備事業」ということで、(1)の「施設整備」の３行目に、西五反田三丁目の新しいタイプのケアホーム西五反田等が記載されておりますが、これは後ほどご報告をさせていただきます。\n１ページおめくりいただきまして、６４ページになりますが、そのほか、「社会福祉施設職員住宅提供事業」、それから、「ホームヘルパーの養成講習」を年３回行っているところでございます。\n最後でございます。６５ページになりますが、「品川介護福祉専門学校修学資金貸付事業」ということで、実績にあるとおり、平成１４年度においては在籍数７７名のうち、４６名の方に就学資金の貸し付けを行ったというものでございます。"},{"i":70,"speaker":"蓼沼高齢事業課長","text":"それでは、高齢事業課の事務事業概要についてご説明いたします。\n私どものほうは、今、早津高齢福祉課長がご説明いたしました要介護高齢者へのサービス以外の、基本的に元気な高齢者の方の生きがいづくり、あるいは社会参加といった事業を中心に高齢者の住宅あるいは老人医療といったものを所管してございます。\nまず４６ページをご覧いただきいたと思います。\n４６ページ、３の「生きがいづくりと社会参加促進事業」でございます。\n(1)の「高齢者お祝い事業」、シルバー成年式とあります。これは７０歳の方をきゅりあんにお招きして、記念式典でお祝いをするというものでございます。\nそれから中ほど、長寿お祝い事業、高齢者の方の長寿をお祝いし、敬老の日に品川区内共通商品券を配布するというものでございます。\n１枚おめくりいただきまして、(2)の「シルバーパスの交付事務」。これは都の事業でございますけれども、区といたしましては、実施主体のバス事業者に対して、広報によるＰＲですとか、会場の広報窓口の提供等で支援をしているというものでございます。\nそれから次の(3)の「高齢者社会参加プログラム促進事業」。これにつきましては、高齢化が進む中で、要介護高齢者へのサービスを充実する一方で、元気な高齢者も非常に多いということで、８割強、９割弱の方が元気な高齢者ということで、そういった方たちの社会参加を促進していこうということで、新たな高齢者像を踏まえ、多様なニーズに対応して社会参加を促進するものであり、平成１３年度に策定いたしました社会参加プログラムに基づきまして、今重点的に取り組んでおりますのがボランティアへの参加促進、そして就業ということでございます。ボランティアにつきましては、特に高齢者クラブのフライサポート活動に積極的に取り組んでいただこうということで、品川区高齢者クラブ連合会につきましても、組織が従来の７地区から５地区、１３地域制に移行いたしまして、そういったような地域センター単位の組織づくりでボランティアにも取り組みやすくなるような形で行っているというところでございます。\nそれから、就業につきましては、新就業システムとございますけれども、高齢者の就業の総合相談窓口、愛称サポ品川といっておりますけれども、これを昨年の４月にプレオープン、９月にグランドオープンということで、５５歳からの無料職業紹介を中心に、高齢者への就業支援を「ワンストップサービス」という形で行っているものでございます。\n(4)の「高齢者生きがいづくり事業」でございます。高齢者作品展ですとか、次の４８ページでございますけれども、表の下、元気づくりいきいきプラン、これは区の保養所を活用したプログラムでございます。\nそれから、１枚おめくりいただきまして、４９ページ、シルバーダンスパーティー、それから中ほどの高齢者ゲートボール大会、５０ページ、いきいきカラオケ広場、中ほどのいきいき健康マージャン広場、これはお金をかけない、お酒を飲まない、たばこを吸わないといったことをモットーに、マージャンを通じて高齢者の健康づくり、仲間づくりを支援していこうという事業でございます。\nそれから、(5)の「高齢者クラブ等支援事業」、これは花づくり助成事業、そして１枚おめくりいただきまして、５１ページ、表の下でございます。高齢者クラブ運営助成ということで、これは表がございますけれども、会員数による助成金、それからボランティア活動回数による助成金、それぞれ平成１４年度から７割、３割というような割合で助成金を交付しているというものでございます。\n５２ページ、(6)「しながわ出会いの湯」でございます。これは地域の公衆浴場を活用しての仲間づくり、健康づくり、入浴とプログラムのサービスということで、あわせて区内公衆浴場の振興を図るというもので、毎週木曜日に実施をして、参加費は無料ということでございます。\n(7)の「お年寄りと子供のふれあい事業（ふれあい給食）」は、学校給食の機会を通じてお年寄りと子どもがともにふれあって、異世代の交流を促進するというものでございます。\n５３ページ、(8)の「いきいき広場事業」、これは山中いきいき広場と申しますけれども、山中小学校の空き教室を活用しての地域の高齢者の方々に対するさまざまなプログラムを、やはり地域の中高年の方のボランティアスタッフが運営する協議会において実施をしているというものでございます。\n(9)が「社団法人品川区シルバー人材センター運営助成」。\nそれから５４ページ、(10)「シルバーセンターの運営」ということで、区内１６館のシルバーセンターの運営を行ってございます。\nそれから５７ページをお開きいただきたいと思います。４の「高齢者住宅対策」でございます。これは福祉施策としての高齢者への住宅対策ということで、住宅に困窮している高齢者の方に住宅を提供していくということで、まず(1)が「高齢者住宅の運営」ということで、対象が区内に引き続き２年以上居住している６５歳以上のひとり暮らしの方等といったような対象の方に、今現在区立、借り上げを含めて２２０戸の住宅がございますけれども、これの空き室を提供していくというものでございます。\n(2)の「高齢者住宅対策事業」、(1)の住宅運営にプラスしての住宅対策ということで、一つには住宅あっせん、これの対象は住宅運営の対象者の方とほぼ同じでございますけれども、これが５８ページの冒頭にございますけれども、東京都宅地建物取引業協会品川支部との協力によって、住宅のあっせんの事業を進めてございます。\nそれから中ほどの家賃等助成につきましては、今移行措置ということで、平成１８年度末をもって終了の予定でございます。\nその下の高齢者借上げ住宅建設費の借入金利子の助成、これはここ数年実績がございません。\n５９ページでございます。(3)「バリアフリー住宅普及啓発事業」。これにつきましては、東品川三丁目にございます高齢者、障害者にやさしい住宅モデルルーム、これがこの場所を活用しての普及啓発、それからセミナーの開催、講習会の開催等ということで、モデルルームが平成５年に開設をされまして、今年でちょうど満１０周年ということで、記念事業やシンポジウム、モデルルームのリニューアル、それから記念誌の発行といったような事業を予定してございます。シンポジウムにつきましては、来月予定してございますけれども、厚生委員の皆様には改めてご案内を差し上げたいと思いますので、ぜひご参加をいただきたいと思います。\nそれから６０ページの「高齢者や障害者にやさしいまちづくり」でございますけれども、１枚おめくりいただいて６１ページ、(2)に「しながわお休み石設置」とございます。これは区政モニターの方の提案をきっかけに、平成８年度おやすみ石構想というものを作成しまして、これに基づいて三つのタイプのくつろぎお休み石、バス停お休み石、商店街お休み石というものを設置してきてございます。平成１０年度からは、記念お休み石事業というようなものも始めております。\nそれから、６６ページをお開きいただきたいと思います。７番目の「高齢者の医療」でございます。老人保健法による医療ということで、これにつきましては、対象が７０歳以上の方とございますけれども、これは昨年制度が変わりまして、今段階的に７５歳まで５年をかけて引き上げるというふうに変わってございます。昨年の１０月１日現在で、既に７０歳になっている方は引き続き対象者となるということでございます。この制度改正の中身は、そのほかに自己負担割合は所得により２割、あるいは１割といったような設定が導入された部分、それから医療費を受けたときの自己負担限度額月額の見直し、それから償還払いの導入等といったような制度の改正がなされております。\nそれから、６８ページでございます。こちらのほうは、東京都老人医療費の助成制度、いわゆるマル福と申しておりますけれども、本人の自己負担の一部を助成するというものでございます。これにつきましても、平成１９年の６月末をもって制度を終了するということになってございます。\nそのほか６９ページ、中ほどより下、白内障手術後の眼鏡等費用助成事業、あるいは７０ページ、高齢者かかりつけ医・歯科医定着促進事業といったような事業を取り組んでございます。\n雑駁ですけれども、以上でございます。"},{"i":71,"speaker":"山岡保健高齢事業部副参事","text":"それでは最後に、介護福祉専門学校について触れさせていただきます。\n恐縮ですが、資料でございますけれども、先ほど福祉事業部のほうの説明で使いました「品川区の福祉ダイジェスト版」の１１５ページをご覧いただきたいと思います。\nこちらの１１５ページのほうに、「品川介護福祉専門学校」の説明が簡単に記載されております。本校は品川区内の福祉人材を確保・充実することを目的として、平成７年４月に設置されたものでございます。学校の性格としましては、厚生労働大臣指定の介護福祉養成施設ということで、昼間部２年制、専門課程の介護福祉学科を置いているものでございまして、卒業しますと、介護福祉士の資格を得ることができます。運営は、品川区社会福祉協議会が行っているものでございまして、区および区内の社会福祉法人の支援を受けて運営しているものでございます。この予算のところで１億１,０００万円余の金額が出てございますが、このうち２,０００万円強の助成を品川区から受けて、残りは学生の納付金等で賄って運営しているものでございます。定員につきましては、１クラス４０人、１学年１クラスで、８０人、先ほど申しましたように、２年制でやってございます。平成７年に開校しまして、丸８年がたちまして、９年目に入ったところでございます。第７期生が３月に卒業しまして、合計で２８１名の卒業生を出したところでございます。事業内容としましては、この学校の運営のほかに、品川福祉カレッジ、あるいはホームヘルパー養成講習会の開催といったものを、区から受託して運営しているものでございます。\nこのうち、品川福祉カレッジにつきましては、先ほど高齢福祉課のところで出てきましたところをちょっとおあけいただきたいと思います。「高齢者福祉編」の３４ページでございます。\nこちらの３４ページの中ほどから、福祉カレッジについて説明がされております。この品川福祉カレッジにつきましては、既に介護サービスの担い手となっております介護の仕事に従事している方、例えばケアマネジャーであるとか、あるいはホームヘルパーであるとか、こういう方を対象に、その専門性、実践力の向上を図り、福祉人材のレベルアップを図るという目的で区のほうの事業として、私ども品川介護福祉専門学校が受託して運営しているものでございます。\nそこの下の平成１４年度、１５年度とちょっとご覧いただきたいと思いますが、平成１４年度につきましては、ケアマネジメントコースおよび主任ヘルパーコース、二つのコースで実施したところでございます。今年につきましては、このほか、オプション講座ということで、事例検討講座あるいは医療知識講座等を開催いたしまして充実を図っているところでございます。\n予算額６００万円、これは区のほうの予算でございますが、これ以外に受講生の受講料をあわせて介護学校のほうで運営しているものでございます。\n簡単でございますが、以上でございます。"},{"i":72,"speaker":"塚本委員長","text":"説明が終わりました。ご質疑ございますか。"},{"i":73,"speaker":"大西委員","text":"先ほどの質問の続きですが、配食サービスについては二本立てという話がありましたが、一方の選択しかないということで、現時点では週に２食ということですが、これは月曜から金曜まで各小学校ならびに中学校が食事の準備をしていると。数が多い少ないはあると思うんですが、希望者があれば、私は昼の分も、それとまた夕方の分もということを、全食で言いますと１０食ぐらいですか、また、ボランティアの配る方が足りないということであれば、学校に来れるような状況であれば、学校で食事をとっていただくとか、そういう形でより多くそういうサービスをできないものかと考えているんですけど、いかがなものでしょうか。"},{"i":74,"speaker":"早津高齢福祉課長","text":"学校の給食を使った配食サービスにつきましては、先ほどもご説明の最後に申し上げましたように、今直接には、区民生活事業部の地域活動課が行っているところでございます。ただ、この事業につきましては、ねらいといたしまして、身体が少し弱っているために調理が不自由だというような方を主な対象にしているわけですけれども、ただ、これは給食を配食をするということだけではなくて、まさに地域の学校の給食を使って、地域の方が、ふれあいサポートという名前がありますけれども、その気持ちを届ける、あるいは安否が大丈夫であるかというようなことを確認すると、こういったねらいで行っております。そのために週２回、火曜と木曜という２回ぐらいのサービスがよいのではないかというようなことで運用されているものというふうに理解しております。ただ、先ほども申し上げましたが、この事業は、ふれあいサポート活動の大きな中核的な事業になっておりまして、ふれあいサポート活動自体、各地区で今後どのように展開していくかというものを地域センターを中心として検討していくというように聞いております。その中では、各地区の特性に応じて、また検討がなされるのではないかというふうに思いますけれども、直接の所管ではないものですので、聞き及んでいるあたりのところをご説明させていただきました。"},{"i":75,"speaker":"鈴木（ひ）委員","text":"介護保険のところの３４ページの特別養護老人ホームの入所調整のところなんですが、入所調整の一定の基準というふうなことなんですけど、決算特別委員会のところでこの基準をぜひ公表してほしいということで質問して、検討していただけるというご答弁をいただいたと思うんですけども、その後どうなったのかということを１点お聞かせいただきたいと思います。\nそれともう一つ、４２ページの高齢者生活支援事業の1)の生活支援訪問介護援助事業のところにちょっと当てはまらないかもわからないんですけども、６５歳未満の方で、介護が必要だけれども、１５疾病に入らないけど、自分では生活もできないという、例えばがんの末期の方ですとか、ほかの疾病で、そういうふうな方への介護という手だてというのは、何か方法があるのか、また、そういうふうなところで検討がされているのか、ちょっとそのことについてお聞かせいただきたいと思います。"},{"i":76,"speaker":"早津高齢福祉課長","text":"まず、特別養護老人ホームへの入所調整の基準でございますが、私どものほうでも当初からさまざまな試みをし、微調整もいたしまして、今年の４月に公開してもよい範囲というものを定めまして、それについて要請があれば公開させていただいております。それが１点でございます。\nそれから２点目の自立支援の方の生活援助でございますが、これはもともと要介護の認定を受けていない方ということでございますので、具体的なケースについては、支援センターのケアマネージャーとちょっと相談をしていただきながらということになりますが、一定の身体状況の弱まりがある、例えば、重い物が持てないために買い物が不自由だというような方にも、買い物サービスというような形でやっておりますので、具体的にその方の状況等を踏まえて対応できるかと思います。具体的なことについては、支援センターのケアマネージャーを通じてのお話をさせていただければと思います。"},{"i":77,"speaker":"鈴木（ひ）委員","text":"ぜひこの入所調整の基準については、私もいただきたいと思うんですけれども、ここの場でもちょっとご報告していただけたらいいのかなと思うんですけど、それはちょっとご検討いただきたいと思います。\nそれともう一つ、４６ページなんですけど、長寿お祝い事業のところが出ているんですが、ここのところで、見きれていないのかもしれないんですけど、長寿お祝いの金額というのがちょっと見えないんですが、金額については書かれていないのか、書かれていないんでしたら、ぜひここに書いていただけたらと思うんですけども、そのことについて１点と、それからあと、６１ページの荏原中延駅のエレベーターの整備助成のところで先ほどご報告いただきましたけど、このことについては、また改めてこの委員会の中でもご報告いただけるのかどうか、そのことについてお聞かせください。"},{"i":78,"speaker":"蓼沼高齢事業課長","text":"長寿お祝いの金額でございますけれども、申し上げますと、１００歳以上の方が３万円相当の商品券、それから白寿の方が２万円相当、そのほかの方は５,０００円相当ということでございます。\n表示については検討させていただきます。"},{"i":79,"speaker":"早津高齢福祉課長","text":"荏原中延駅へのエレベーターについては、まだ詳細のことは詰まってございません。しかるべき段階で、もし必要であれば、当委員会でもご報告をさせていただきたいと思います。"},{"i":80,"speaker":"須藤委員","text":"「保健編」のほうで、３４ページに関係するんですけれども、プール熱という疾病が近年増えてきているという話なんですけども、ここで不適というのが４件報告されていますけども、このくらいのものなら問題ないと考えるのか。それからプール熱について、これからプールに入る時期なんですけども、それに対する対応の仕方というのは、行政側で何か考えていらっしゃるかどうか。\nそれからこれは、９７ページの表なんだけども、下の数字が横に読むようにつくってあって、５２ページにはちゃんとこの表に合うようにつくってあるんだけども、何か理由があってこうなっているのか。もし、皆さんに見やすいんなら、横に数字が見えるようにつくっていただければ、ほかの表と整合性があるんだけどというふうに思いますけども、いかがでしょうか。こうしなきゃいけない何か理由があったんならしようがないだろうけども。もう少し見やすくつくったほうが整合性があると思うんですが、いかがですか。"},{"i":81,"speaker":"島袋品川区保健所衛生課長","text":"許可プールの不適施設、４施設でございますけど、一応残留塩素関係では、塩素殺菌ができているかと、過マンガン酸カリウム、これは人間の汗等をはかるものですけど、一応不適が出ましたので、こちらのほうで出ないように指導しております。"},{"i":82,"speaker":"小林品川区保健センター保健サービス課長","text":"現在、品川区自身では、定点報告としてはまだ１件から３件ぐらいでそんなに多くありませんが、都のレベルでは、倍レベルになっているという状況ですので、これからも注意していきながら、機会があれば指導していきたいと思っております。"},{"i":83,"speaker":"田中健康課長","text":"９７ページの表は大変失礼いたしました。昨年は縦に平成が並んでいたんですが、どこかの編集の間違いで横になってしまって、見苦しい点、申しわけございません。本番でまたつくり直しますので、訂正させていただきます。"},{"i":84,"speaker":"塚本委員長","text":"ほかにございませんか。\nそれでは、以上で事務事業概要の説明を聴取いたしました。\n────────────────────────────────────────────\n３．報告事項\n(8)「ケアホーム西五反田」・「さくらハイツ西五反田」入居者募集、モデルルームの開設について"},{"i":85,"speaker":"塚本委員長","text":"次に、報告事項に移ります。\n報告事項は９件ございまして、予定表では、こうなっておりますけれども、早津高齢福祉課長と新美保健高齢事業部長のご都合があるということで、順序を変えたいと思いますので、よろしくお願いいたします。\nまた、報告事項はこの後の委員会でも質疑をとりわけてしなければいけないこと等もございますので、その辺のめり張りをひとつよろしくお願いしたいと思っております。\nなお、当委員会は５時１０分ぐらい前をめどに運営していきたいと思いますので、よろしくどうぞお願い申し上げます。ご協力次第でございます。"},{"i":86,"speaker":"早津高齢福祉課長","text":"「ケアホーム西五反田」・「さくらハイツ西五反田」の入居者募集、モデルルームの開設についてというものをご覧いただければと思います。裏表１枚のこちらの用紙でございます。そのほかに、パンフレットが３部ついております。それでは、ご説明をさせていただきます。\n事業目的のところにありますように、西五反田三丁目、旧荏原市場跡地におきまして建設中の施設、一つは、介護が必要となった高齢者のための個室型介護専用施設「ケアホーム西五反田」と命名させていただきました。それと、元気なうちから入居し、介護が必要になっても住み続けられる「高齢者の安心の住まい・さくらハイツ西五反田」が、平成１５年１２月に竣工し、１６年４月に開設をしますというあらましでございます。建物につきましては、上の写真のコピーがありますけれども、まず目につきます一番右のＡ地区高層棟が３１階建て区民住宅でございます。隣にＢ地区の都営住宅を挟みまして、一番左にＣ地区ということで、高齢者施設等が入りますビル、後ろに高層ビル１４階建て、手前に４階建てのビルになっております。\nこちらのピンク色のパンフレット、「ケアホーム西五反田」・「さくらハイツ西五反田」と書いてあるものの１ページをめくっていただきますと、左下でございます。今の写真の、もうちょっとカラー刷りにしたものがございます。そこにありますように、手前の４階建て、ちょっとでこぼこしております建物がケアホーム、要介護の高齢者を対象とした個室型のケアホーム、後ろの１４階の建物のうち、２、３、４階がお元気な方がお入りになるさくらハイツ西五反田と、こういう建物の関係でございます。\nもとの説明資料に戻っていただきますと、今あらまし説明してまいりましたが、施設の概要でございます。耳なれない言葉でもありますので、ちょっとしつこくて恐縮ですが、ケアホーム西五反田の内容ということで、要介護高齢者を対象としまして、全室個室です。居間・食堂がある小規模な９人を１組としたユニット方式で介護するということで、ユニットケア方式といってございます。定員は９ユニット、つまり、９人の１ユニットが９個あるということで、９×９で８１人ということになります。大きく分けて二つのタイプということで、一つは、重度の介護が必要となった、身体介護を中心とした介護専用ホーム、もう一つですが、痴呆性高齢者の特性に着目した痴呆性高齢者のグループホームというような形で３フロアを使い分けていきたいと思っております。\n2)でございますが、利用料につきましては、選択制をとりまして、そこに記載のものは、要介護３の場合のモデル例でございます。アといたしまして、選択制の一つは、一時金併用払い方式ということで、入居時に上乗せ介護費、これは月１０万円分をお支払いいただくものですが、それを８年分前払っていただくことで９６０万円と、その他預かり保証金３０万円ということにいたしまして、月額の使用料については１６万円ということで、この１６万円の中には括弧にありますように、食事代、個室代、介護サービス等すべてを含むということで、通常のお部屋の光熱費も含んでおります。冷暖房費はちょっと別途になるんですが、ということでございます。\n次のページにもう一つの支払い方式としまして、月払い方式、均等払いということで、あらかじめの９６０万円がない場合ですので、こちらは２６万円の毎月の払い、一時金が３０万円ということでございます。\n3)ですが、このケアホーム西五反田の入居者の決定につきましては、従来の特別養護老人ホームと同様に要介護度、それから介護の困難性、緊急度等を審査の上、入居者を決定してまいります。\n次に、もう一つの施設でありますさくらハイツ西五反田、これは南大井のさくらハイツの２号店的なものとお考えいただくのがよろしいかと思います。1)にありますように、心身状況が自立した高齢者を対象とした「高齢者の安心の住まい」でございまして、将来介護が必要になったときには、ケアホーム西五反田に基本的に移り住むということです。そのために、入居者の相互扶助による介護の安心基金を設置いたしまして、この基金のほうから介護ケアホームに移った後の上乗せ介護費用を充てていくというものでございます。\n施設構成、2)でございます。１人室が４２平米で３５室、２人室が５６平米で４室ということで、合計で４３人の方が定員ということになります。利用料金につきましては、単身のモデルを書いてございますが、入居時一時金として家賃の一部前払い金および介護安心基金、内訳が書いてなくて恐縮です。９５０万円のうち、家賃の一部前払い金が３００万円、介護の安心基金が６５０万円でございます。そういたしましたときに、月額の使用料は食事代、家賃、事務費等を含むで、年収によって違いますが、１１万円から１４万円程度、こちらのほうは先ほどのケアホームと違いまして、光熱水費はお元気な方ですので、それぞれ自分で、実費でご負担いただくということになります。入居者の決定につきましては、資格要件等を確認して公開抽選で行います。そのほか、地元地域であります大崎第一地区の在宅介護の拠点として在宅介護支援センター、在宅サービスセンターならびに訪問看護ステーションを併設いたします。さらにその他といたしまして、大崎第一地域センター、区民集会所、それからクリニック、薬局、区民住宅等を併設という建物でございます。所在地はそちらに記載のとおりでございます。\nモデルルームの開設につきましては、５月２８日から行っておりまして、６月２２日まで行います。午前１０時から午後４時までということで、開設期間中は土・日も開設をしております。昨日までの１１日間の実績でございますが、モデルルームへの来場者は７２７名ということでございます。さらにこの後の入居の募集期間でございますが、二つに分かれております。ケアホーム西五反田については６月２日から７月２５日まで、さくらハイツにつきましては、８月８日までとなっております。６月６日現在での募集の状況でいきますと、ケアホームのほうが１７名、さくらハイツのほうが３２名というような募集になっております。４日間での状況でございます。設置・運営はさくら会が設置し、ミサワホームグループのマザアスが連携して運営するということでございます。問い合わせ等はその記載の場所ということでございます。\nそれから、お手元に先ほどちょっと触れましたパンフレット、それから、さくらハイツとケアホームの説明書および申込書がついているものを添付させていただきました。\n私のほうの説明は以上にさせていただきます。"},{"i":87,"speaker":"塚本委員長","text":"説明が終わりました。ご質問ございますか。"},{"i":88,"speaker":"鈴木（ひ）委員","text":"ケアホーム西五反田のほうなんですが、ここの説明だと、重度の介護が必要な高齢者と、それからあと、痴呆性の高齢者ということで、二つのタイプということになっているんですけど、今までは三つのタイプというふうになっていたんじゃないかなと思うんですけど、去年のプレス発表でも、軽度の介護の方と、それから重度と、それから痴呆性というふうに３タイプになっていたんじゃないかなと思うんですけど、ここのところがどうしてこういうふうに変わったのかということが１点と、それからあと、このさくらハイツと、ケアホームについて、それぞれ需要がどれくらいというふうに区としては考えているのか、そこら辺のところもお聞かせいただきたいと思います。\nそれともう一つ、新聞報道でも５月２７日の読売新聞で、終身介護マンションというふうなことで報道がありましたけど、ここのところを読むと、さくらハイツに入られた方が将来介護が必要になったら速やかにケアホームのほうに移れる仕組みというふうな感じで書いてあるんですけれども、そこら辺のところの仕組みというふうなのが、どういうふうな仕組みになっているのかについてお聞かせいただきたいと思います。"},{"i":89,"speaker":"早津高齢福祉課長","text":"まず、ケアホームのほうが介護専用と痴呆の二つになった理由ということでございます。痴呆性高齢者につきましては、かねてから一つ設けていたんですが、身体系の方につきまして、重度の方と中度の方のような区分けをあえてしておりましたんですけれども、実際の運営を考えていきますと、それほど固定的なものでもありませんので、この際ほかの特別養護老人ホームと比べても大体重度な介護が必要な方ではないかということで、あまり重度と中度と区分けると、じゃあ重度と中度の区分けの間は何かみたいなお話になりますので、身体介護で一定の介護が必要な方というような趣旨でざっくりと区分けしたほうがわかりやすかろうというふうに考えたものでございます。\nそれから、速やかにケアホームに移るということでございますけれども、この速やかにというのは、さくらハイツでの生活がかなり存続が難しいと、こういうようなことになった場合に、ケアホームに移れますということを、そのときに「速やかに」という表現を新聞記者の方が使ったわけでありますけれども、これは昨日までお元気だったのが急に今日ぐあいが悪くなって、速やかにというようなことは通常は考えられないわけでして、徐々に状態が悪くなっていく。さくらハイツでも、介護力はありますし、在宅のヘルパーを使うこともできます。ご本人がこういう場合には、ケアホームにすぐ移りたいかというと、さくらハイツでなるべく頑張りたいというようなお気持ちも当然あります。したがって、ご本人の気持ちとケアホームへの空きとかというようなことも考えて、必要になった段階で順調にといいますか、速やかに移り住むことができると、こういうシステムをつくったと、そういう趣旨でご理解いただければと思います。\n需要の見込みでございますが、実際まだ申し込み等なので難しい面がございます。モデルルームの見学者が１１日間で７２７人というようなこと、それから６日間での募集が今申し上げたようなことというのを考えますと、さくらハイツについては１０倍を超えるような方もお見えになるだろうし、ケアホームについても、かなり定員を超えるような方が申し込みされるのではないかというような感じでおります。\nすみません。資料をちょっと訂正させていただきたいんですが、間違っておりました。募集期間のところで、ケアホーム西五反田が７月２５日までになっていますが、上下逆でして、「ケアホームの場合が８月８日まで」「さくらハイツのほうが７月２５日まで」ということで、ちょっと資料の書き方を間違えてしまいました。訂正をこの場でさせていただきたいと思います。"},{"i":90,"speaker":"鈴木（ひ）委員","text":"そうすると、ケアホームのほうに入る方というのは、重度ということだと、特別養護老人ホームと同じ、特別養護老人ホームだと大体要介護３以上というふうなのが基準になると思うんですけど、そういうふうに要介護３以上というふうなことで考えていいのかということと、それからそうすると、さくらハイツで南大井にもあると思うんですけど、ここでは介護も受けられるということなんですけど、大体どの程度まで、要介護で言えば、身体系の要介護で言えば、どの程度までそのさくらハイツで介護が受けられるのかというふうなところもちょっとお聞かせいただきたいと思います。\nそれと、ケアホームのほうの入居者の決定なんですけど、特別養護老人ホームと同じような基準で審査の上というふうなことになっているんですけど、これは特別養護老人ホームと同じ入所調整会議というふうな形でかかるのか、また別なところで審査されるのか、そこの審査会のところがどういうふうになっているのかについてちょっとお聞かせください。"},{"i":91,"speaker":"早津高齢福祉課長","text":"まず、ケアホームへの入所条件というのが要介護３以上かどうかというのは、これは実際上、どのぐらい応募されてくるか、あるいはその方の身体状況がどのようであるかということとも影響が出てまいります。こちらの説明にもありますように、要介護度ですとか、在宅期間ですとか、年齢ですとか、これは特別養護老人ホームの入所調整と似たような基準をもって施設入所の必要性というふうに考えますので、これによって多少変わってくるかというふうに思っております。\nそれから、さくらハイツでどのぐらいまで介護できるかということでしたが、要介護２ぐらいまでは大丈夫でしょうし、完全バリアフリーに設計されておりますので、在宅環境としては、かなり優れた住居環境になっておりますので、これが外からの在宅サービスを活用することであれば、かなりのものができると思います。この場合に、ご本人のご希望も出てまいりますので、そのときにケアホームがより適切か、あるいは在宅で頑張ることがよりよいのか、２人部屋と１人部屋では、また介護環境も変わってまいりますので、その辺のところがさまざまあるかと思いますが、おひとり暮らしの場合でも、要介護２ぐらいまでだったら大丈夫ではないかなというふうに私どもは、今のところ想定をしてございます。\nそれからケアホームへの入所調整につきましては、基本的には特別養護老人ホームの入所調整会議と同じような形をとりますので、そちらのほうを活用していきたいとも思うんですけれども、また状況によって、入所の審査については、またもう少し様子を見て、具体的なところは検討してまいりたいと思います。"},{"i":92,"speaker":"鈴木（ひ）委員","text":"一つは、さくらハイツの方が優先というふうになるわけではなくて、さくらハイツの方も一般区民も同じというふうなところで基準としては考えられるのかというふうなところと、審査というふうなところがまだはっきりしないんでしょうか。"},{"i":93,"speaker":"新美保健高齢事業部長","text":"ケアホームのほうでございますけれども、さくらハイツは南大井が１回経験をしております。ケアホームは初めての施設ということで、介護つきのケアハウスということになるわけですが、初めてでございまして、他に例がないものですから、少しずつ試行的にやっていこうということで、今回の期間は一次募集という位置づけでございます。一定の応募状況によって、あと、先ほど言ったように単なる抽選ではなくて、一定の基準を設けて、ケアホーム用の入居審査会といったものを設けていきたい。少なくとも、今年度については、そういうふうにしていきたいと思っております。\nそのときに、特別養護老人ホームの入所調整の仕組みをつくり上げておりますので、それとの連携というのはきちんととりながら、あるいは調整、均衡といいますか、それをとりながら、８月８日までの一次募集期間ですので、９月の段階までに、今ご質問のようなことを含めて精査をした上で、１回目の入居審査会をやり、二次募集を秋にもう一回一定の枠でやっていくというので、開設当初の入所者、入居者審査を考えているところでございます。\nさくらハイツはケアホームへの、特に要介護３あるいは２でも痴呆性高齢者の場合は要介護度が若干低くてもなかなか在宅おひとり暮らしは難しい状況がありますので、これはさくらハイツのほうはケアホームへ移り住むことを条件に安心の基金を拠出していただいているので、西五反田については、全員じゃございませんので、必要な方は移り住みを安心の保証にしているところでございます。８１人ございますので、在宅から直接ケアホームへ入居いただくことが大半になりますが、安心の住まいは当然、先に重度になって個室で難しくなれば、ケアホームへ移り住むという前提で入居いただくということになります。"},{"i":94,"speaker":"塚本委員長","text":"鈴木委員、ほかの事項もございますし、他の委員もございますので。"},{"i":95,"speaker":"鈴木（ひ）委員","text":"そのさくらハイツというのは、今回できるさくらハイツだけがそういうふうなことなのか、それとも、南大井にできているさくらハイツというのは、関係がないのか、そのことだけ、最後にお願いいたします。"},{"i":96,"speaker":"新美保健高齢事業部長","text":"これもいろいろ検討しているところですが、南大井は南大井で一つの在宅介護の仕組みがありますが、それになかなか寄りがたく、ケアホームのほうが、常時スタッフがいるということがありますので、望ましい場合は、１件１件の審査になるかと思いますが、そちらからケアホームへの移り住みも一定の条件のもとで、同一法人が運営するものですので考えていく必要があろうかと今のところ考えているところでございます。お一人お一人審査しながら移り住みということになろうかと思います。"},{"i":97,"speaker":"塚本委員長","text":"ほかに本件に関してご質問ございませんか。\nそれでは、(8)の報告事項を終わります。\n保健事業部関連のほうを先に聴取したいと思います。\n────────────────────────────────────────────\n(6)「区民健康づくりプラン品川」の策定について\n(7)「社会福祉法人かもめ工房」設立準備会について"},{"i":98,"speaker":"田中健康課長","text":"それでは、私から(6)の「区民健康づくりプラン品川」の策定、および「社会福祉法人かもめ工房」設立準備会、あわせて説明いたします。\n「区民健康づくりプラン」、先ほど事務事業概要の説明の中でお話しさせていただきましたが、３月策定をさせていただきました。今日初めて議会の関係の方に、この厚生委員会でお配りいたしました。\n資料の７３ページをご覧いただきたいんですが、これは平成１３年の１２月に区民会議というものを立ち上げて、実際上、この３月まで議論していただいて策定したものでございます。あわせて、これからいろいろ町場に呼びかけるためのリーフレットを作成させていただいております。\nそれで、内容的には今日いろいろ時間の制約もございますので、次回等の委員会で委員長のほうに説明の場をお願いしたいと思っておりますので、今日はお渡しということでご承諾をいただければと思います。\n次にもう一つ、「社会福祉法人かもめ工房」設立準備会についてということで、ご報告申し上げます。\nこれまでの経過でございますが、平成１３年１１月に当委員会におきまして、現大崎第一地域センターが先ほど来ケアホーム西五反田等への建物が完成しますと、移転いたしまして、あの４階建てがあきます。そこに精神障害者のための社会福祉施設でございます通所授産施設と、生活支援センターを整備する計画をということでご報告を申し上げているところでございます。その後、昨年４月にこの施設等に関する基本構想検討委員会というもので検討いただきまして、今回そういうものをベースにしまして、この設置運営主体、新しい法人をということでございまして、この６月４日におかげさまで発起人の方の呼びかけによりまして、設立準備会が立ち上がった次第でございます。\nそれで、この下のほうの枠の中の事項が確認されましたので、ご報告をさせていただきたいということでございます。\nまず、「第１回社会福祉法人設立準備会の検討内容」ということで述べさせていただいておりますが、(1)基本方針としまして、この精神障害の方のための通所授産施設および地域生活支援センターの設置・運営主体については、品川区とのパートナーシップに基づき、地域の関係諸機関の参加・協力のもとに、社会福祉法人を新設する。その準備会をということでございます。\nあらかじめ法人の事業内容ということで確認いただきましたのが、精神障害者通所授産施設定員約３０名のもの、これは現かもめ工房等運営委員会の三つございます作業所の一つをこちらに発展させる形で動かすという内容でございます。\nそれから新たに地域生活支援センターを開設します。ならびに、この法人ではやはり現在の共同作業所、一つを移転させましても、二つ作業所が残ります。その法人化等も考えておりますが、あと、それから区のほうからは、グループホーム「かもめハウス」という南大井のほうも委託をしてございます。この受託をこの新法人でお願いしたいという内容でございます。\nなお、法人設立の資産ということでございまして、これが法人の認可のための要件になるわけなんでございますが、これは土地については品川区から法人に対して無償貸与、建物については、品川区から法人に対して無償譲渡をする、これは以前から報告されていた内容でございますが、これを法人の基本財産にするということで、この法人の認可が受けられるというふうに私ども整理をしてございます。\nそれから、準備会の委員構成および役員でございますが、医療福祉の学識経験者、地域の福祉関係者、地域の関係者等１０名で構成するようにお願いをしてございます。会長以下の役員もこの日に互選で選出されております。\nなお、社会福祉法人設立の趣意書でございますが、これは来年度認可のための一番大事なポイントの部分でございますけれども、裏面に６月４日付で趣意書ということで確認をいただきました。現在までの国なりも含めた区のこの方面に関する方向づけが一定程度確認をされまして、中段ほどでございますが、平成１０年には地域保健計画の中で区としても具体的な方向が示されまして、グループホーム、それから平成１４年のホームヘルプというふうに開始をされている。そこで、今後総合的にこのサービスを提供する主体が必要だということで、地域生活支援センター、それから授産施設を開設することを含めてこの法人を立ち上げるという内容の趣意書をいただいてございます。\nそれから前に戻りまして、４点目でございます。この際、準備会の規約の確認の中で、名称の決定をお願いしました。「社会福祉法人かもめ工房」という名前で今後準備会を進めるという内容になってございます。今後のスケジュールでございますが、今回の準備会の発足、それで、法人認可にはいろいろ整備のための補助金ですとか、工事の期間等がございまして、現在私どもが考えておりますのは、平成１６年の８月ごろに新法人の正式な認可を受ける。それから工事をいたしまして、整備工事をいたしまして、１６年度３月に一応しておりますが、できるだけ早い時期に開設をというふうに考えてございます。"},{"i":99,"speaker":"塚本委員長","text":"説明が終わりました。ご質疑はございますか。"},{"i":100,"speaker":"須藤委員","text":"いい形が出てきたなと思うんですけども、法人設立の資産のところで、「建物については、法人に対し無償譲渡し」となっていますけども、その上に「品川区とのパートナーシップに基づき」という表現になっているから、そんなに懸念しなくていいんだろうけども、いわゆる建物を直したり、授産所に合わせたりというようなことがあろうかと思うんだけども、その辺の対応も考えておいてやらないと、建物が相手さんだよ、法人だよといっても、なかなかそこまでの費用というのも大変だろうと思うので、その辺のお考えはいかがでしょうか。"},{"i":101,"speaker":"田中健康課長","text":"ご説明が足らなくて申しわけございません。建物は現状のまま移転をしますと、法人のほうに移転をすることになります。というのは、整備補助、かなりの額を私どもも想定しているんですが、国庫補助を受けるためには、法人が認可されて、法人が受けて工事をするという必要性があります。区がそのままやってしまいますと補助金が入りませんので。それで、一応そういう形式をとるということでございまして、現在区のほうは、一応補助に関係のない設計の部分を詰めさせていただいております。ですから、認可を想定しています平成１６年の８月以降、工事期間を半年ほど見ているというのが現状でございます。"},{"i":102,"speaker":"須藤委員","text":"だから、いわゆる上のパートナーシップをちゃんととれていますよということで理解していいわけですね。工事にかかるよということなんだけども、そういうこともちゃんと入っていますよと、考えていますよということで理解していいわけですね。"},{"i":103,"speaker":"鈴木（ひ）委員","text":"社会福祉法人の設立準備会というのが６月にできるという、そういうふうな状況だと思うんですけど、この準備会、一番初めには、基本構想検討委員会というのがあったと思うんですけど、その検討委員会と、それから準備会と、社会福祉法人というのが、ちょっとそれぞれどんな方々がされていたのか、社会福祉法人かもめ工房というものの主体はどういうものなのか、そして、その三つのところの関連というのはどういうふうになっているのかというところがちょっとよくわからないので、教えていただきたいと思います。"},{"i":104,"speaker":"田中健康課長","text":"設立準備会自体は１０名の委員の方で構成していただいておりますが、今委員からご指摘のあった平成１４年４月の段階で基本構想委員会には、この設立準備会に今回かかわっていただいた委員に近い形の方にお集まりいただいております。といいますのは、もともと私どもの品川区の精神福祉関係につきましては、作業所等を運営しているかもめ工房等運営委員会というのがございますけども、そちらと同時に精神保健のいろんな福祉の連絡協議会を区が一応外郭団体としてここ何年か持ってまいりまして、この政策等への提言をいただいてまいりました。今回基本構想委員会のときに新しい法人にというときに、まずかもめ工房、現在まで頑張っていらっしゃっている皆さんの運営委員会のほうから、できる限り地域バランス、それから専門領域等を含めて、委員の方をお願いしてまいりましたし、それからあと、精神福祉連絡協議会というところでいろいろ今までご提言いただいた学識経験者の方等にご参加をいただいて、そういう形で現在進めておるところでございます。"},{"i":105,"speaker":"鈴木（ひ）委員","text":"何となく漠然としていて、よくわからないんですけど、例えばここで、じゃあ、今度の準備会の委員の医療福祉の学識経験者、地域の福祉関係者、地域の関係者というところは、具体的にどういう方なのか、そしてまた、社会福祉法人というのがどういう方々がされるようになるのか、ちょっと具体的なところで教えていただけないでしょうか。"},{"i":106,"speaker":"田中健康課長","text":"今回会長に選任されましたのは、福栄会理事長でございます。現在、かもめ工房等運営委員会の顧問をしていらっしゃいます。それから、精神福祉連絡協議会等の委員長。現在のかもめの運営委員長。それから福栄会の常務理事。それから社会福祉協議会から、事務局長。それからかもめ会の会長で、いわゆる家族会でございますけど、こちらからお２人、こちらは地元の町会長でもございますので、近い形の町会長でございますので、かもめ会のほうからご推薦をいただいた形でおります。\nそれから年輪の会といいまして、回復者団体、こちらもかもめ工房等運営委員会の会長。それからかもめ工房等の運営委員会の事務局長。会計監事にシルバー人材センターの事務局長ということで、１０名の委員でございます。"},{"i":107,"speaker":"塚本委員長","text":"品川区から建物を無償譲渡、土地は無償貸与という社会福祉法人の設立ですが。その法人なんですけれども、法人というのは永続性を願って設立されるものですが、社会的役割が変わることは当然あるわけですし、解散というものはどういう組織にも考えなきゃいけないことですが、そういうことを想定して福祉法人というものはされているのかどうか。そのときに、品川区が与えたファンデーションというものがどういう形になるという約束が設立時になされているのかどうかということを聞きたいんですけれど。"},{"i":108,"speaker":"田中健康課長","text":"法人の場合には、まずどういう業務を行うかというのは、ご存じのとおり定款等でしっかり決まってまいりますので、そういう点では、一応そこに違ったことが行われる場合には当然はっきり法人からの報告等があると思います。それで、当然解散等もあろうかと思うんですが、通常私ども、ほかのところでやっている場合には、その目的から何年間この建物自体をほかの目的に転用しないことですとか、そういうお約束は当然させていただいておりますので、こちらにつきましても、十分そういう部分も注意して、法人の設立に立ち会わせていただきたいというふうに思ってございます。"},{"i":109,"speaker":"新美保健高齢事業部長","text":"確かに社会福祉法人は永久的な組織ということで想定されているわけですが、委員長ご指摘のように将来の状況が全く変更がないとは言えないわけでございますが、そうは言いつつ、土地については無償貸与ですので、もしもそういうことがあれば、お返しいただく。それから、建物については、基本財産としなければスムーズに法人が新設できないということもありまして、建物のほうを無償譲渡、手を入れますが、いずれにしても、この建物の償却期間といいますか、この建物そのものがもう既に３０年近く建っている建物でございますし、今回エレベーター等の改修工事はいたしますが、その建物そのものの価値がある間に大きく変化するということはなかなか想定しにくいこともありますので、可能な限り協定等のお約束等できちんとしばっていきますけれども、法制度上はやはり、単純にはいかないところは、社会福祉法人はありますけれども、それはこれから具体的に詰める段階で今健康課長も言いましたように、区民の不利益になることのないような形の、あるいは適性な財産の利用になるように詰めていきたいと思っております。法人立ち上げ上、どうしても基本財産部分、施設については必要だということが根っこにございますので、その点はご理解いただきたいと思います。"},{"i":110,"speaker":"塚本委員長","text":"日本の組織というのは、そこのところが欠けているんですよね。自分たち、特に官僚のつくったものは永続して当たり前だというような前提に立っております。しかしながら、別の品川区と関係を持つ福祉法人、別人格でございますから、そういうことの関係はきちっとした約束がなければいけないという、お互いに信頼性の高い組織であることは間違いないですけれども、そういう時代に来ているのではないかということをあえて質問させていただきました。\nほかにございませんか。"},{"i":111,"speaker":"鈴木（ひ）委員","text":"今回の授産施設ですけども、これは共同作業所が三つあるうちの一つをここに解消するというか、格上げするというふうなことで説明をされていますけど、共同作業所と授産施設の対象者の違いというふうなところをちょっと一つ教えていただきたいのと、それと予算面では、区から出る予算というふうなのは、それぞれどうなってくるのか、このことについてちょっと教えてください。"},{"i":112,"speaker":"田中健康課長","text":"共同作業所といいますのは、実は東京都の制度でございまして、東京都からは社会復帰のためのそういう作業をしながらということでございますので、それから授産施設というのは、国の法内施設でございます。そこで、一応名目的には授産をしてというような言葉がきっと厳密な意味ではあるかもしれないんですが、一応私どもとしては、両方とも社会復帰施設であるということで、急に今までやっていらっしゃった方がこちらに移転して授産施設に行ったんで、すごいしゃかりきになってといっても、なかなか動かないものですから、そこはうまく含みを持ちながら目的に向けて動きたいというふうに思ってございます。\nそれで、もう一つ予算的なものでございますけれども、東京都のほうの作業所運営の予算を今まで品川区が受けて、それを運営委員会のほうに補助させていただいたわけですけど、今回は運営費補助、現在のところは、実は１０分の１０いただけることになっているので、国庫のほうから受けて、同じく進めたいというふうに思っております。それほど大幅に補助額が動くことではないんですが、都のほうはいろいろ国のほうの制度を使ってほしいという要望を２３区に出しておりますので、より安定的な方向には向かえるだろうというふうには思ってございます。"},{"i":113,"speaker":"鈴木（ひ）委員","text":"じゃあ、共同作業所のほうも、都の施設ということで、全面的に東京都からの補助金だけということで、区からの持ち出しというのはなかったのか、そのことを一つ教えていただきたいのと、ちょっと聞いたところでは、授産施設というのは、三つの共同作業所から状況がもっと次につなげられるというか、もうちょっと全員が全員一つの第３作業所だったら第３作業所の方々が、皆さん授産施設に行けるというよりは、第１作業所、第２作業所、第３作業所のところから選びながら授産施設のほうに行く、じゃないかというふうなことで聞いたんですけど、そこら辺のところと、そしてもしそういうふうなことであれば、第３作業所の方々が全員授産施設に行けないというふうなことになったら、第３作業所がなくなったときのその方たちはどうなってしまうのかというふうなあたりのところがちょっと心配なんですけど、教えてください。"},{"i":114,"speaker":"田中健康課長","text":"区の持ち出し予算はわずかでございますが、今までも区のほうは都のほうからの共同作業所の運営経費を受ける中で極力やってまいりました。それから、今回以降も同じかと思います。それから、第１、第２、第３という作業所からがどうなるかということでございますが、これはまさしくこれから運営委員会といろいろと協議をいたしまして、ですから、第３作業所の方がそっくりといいましても、毎月異動もある中でございますので、それはいろいろ立地条件、希望、皆さんの障害の程度、そういうものをご相談しながら行くはずでございます。例えば、第３作業所から今度のところへ行きたくないという方がいれば、ほかの今の第２作業所とか第１作業所へ行く場合もありましょうし、そういう内容をスムーズに、皆さん、利用者を第一に考えるべきだと思いますので、そういうことは現場のほうとよく相談をしながら進めていきたいというふうに思ってございます。"},{"i":115,"speaker":"鈴木（ひ）委員","text":"区の持ち出しがわずかということなんですが、このところがどれくらいかというのを、じゃあ後で教えていただきたいと思います。よろしくお願いします。\nそれとあと、第３作業所がそのまま行くわけでないということで、行かなかった方が第１作業所や第２作業所に移ればいいと言われても、なかなか環境にすぐ順応するというのが大変な部分があると思いますので、そこら辺のところはぜひ配慮していただきたいということと、それと、今度のこの共同作業所についていえば、品川区は今までも３カ所というふうなところで、今までもここの委員会の中でもいろんなところでもちょっと要望として述べてきたんですが、ぜひこれは他の自治体と比べても共同作業所の数はほんとうに少ないと思いますし、これはあればあっただけ前進するという、そういうふうな種類のものだと思いますので、ぜひ第３作業所をなくすということでなく、またその場所がひどい老朽化しているというふうなことも聞きましたけど、それであれば、場所を違うところも検討していただくということも含めて、ぜひ第３作業所をなくさないで、共同作業所は増やす方向でご検討いただきたいという……。"},{"i":116,"speaker":"塚本委員長","text":"要望ですね。"},{"i":117,"speaker":"鈴木（ひ）委員","text":"要望でお願いします。"},{"i":118,"speaker":"塚本委員長","text":"ほかにございますか。\nそれでは、本件を終了いたします。\n────────────────────────────────────────────\n(9)「いきいき計画２１（平成１５年度～１９年度）」（品川区高齢社会保健福祉総合計画・第二期品\n川区介護保険事業計画）の策定について"},{"i":119,"speaker":"塚本委員長","text":"(9)の「いきいき計画２１」の策定についての報告を受けます。"},{"i":120,"speaker":"高橋介護保険担当課長","text":"皆様のお手元に「いきいき計画２１」の本編と、それからあらましがお手元に届いていると思いますが、今回、これに当たりましては、昨年度制度推進委員会におきまして、第一期の運営状況等を検討しながら３月に策定したものでございます。本日におきましては、この長いものをご説明するのは時間のかかることなので、次回の委員会のときにお願いしたいと思います。どうぞお目通ししていただきたいと思います。よろしくお願いいたします。"},{"i":121,"speaker":"塚本委員長","text":"そのように扱わさせていただきますので、ご理解のほど、どうぞよろしくお願いします。\n────────────────────────────────────────────\n(1)「障害者就労センター」について"},{"i":122,"speaker":"塚本委員長","text":"それでは、もとへ戻りまして、報告事項の(1)「障害者就労センター」についてを議題にいたします。"},{"i":123,"speaker":"日下部障害者福祉課長","text":"それでは、私のほうからお手元に配付をさせていただきましたＡ４判１枚の資料に基づきまして、「品川区の障害者就労支援センターの開設について」ということでご報告をさせていただきたいというふうに思います。\nそれで、こちらの前文にございますように、景気低迷が大分長期化してございます。ということで、よく新聞等でも取り上げられておりますけれども、障害者の雇用情勢が大変厳しくなっているということを踏まえまして、特に職場への適用、そういった点で課題の多い知的障害者の方の民間事業所等への就労機会の拡大と定着化を図るということで、専門の支援スタッフを配置いたしました品川区の障害者就労支援センターを開設するというものでございます。\nその具体的な内容でございますけれども、まず名称といたしましては、こちらにございますが、これはちょっとすみません、障害者が抜けておりますけれども、「品川区障害者就労支援センター」でございます。愛称をつけさせていただきました。障害者の方が自立に向けまして、元気いっぱいに頑張られるようにという思いを込めまして、「げんき品川」ということで愛称をつけてございます。\n場所としましては、品川区の南品川三丁目７番７号、福祉工場しながわ内ということで、表示をしてございますけれども、要するに児童学園ですね、この中に福祉工場も一緒に併存しておりまして、福祉工場しながわと児童学園が準備室を共用しております。その一角を活用して、この就労支援センターを設けようというものでございます。\n開設につきましては、本年の４月ということで、既に開設をしてございます。５月２７日にはハローワークをはじめとしまして、関係者の方にお集まりをいただきまして、説明会を開催させていただいております。これを契機に本格的に活動を開始したというところでございます。\nそれから運営でございますけれども、こちらにつきましては、障害者の親御さんが中心となって設立をいたしましたＮＰＯ法人の「ぴゅあ・さぽーと」、こちらに運営を委託してございます。それから、対象者としましては、主に民間事業所等への就労を希望する知的障害者。それから事業内容でございますけれども、特に知的障害者の方の場合は、就労面だけではなくて、日常の生活面でのサポート、これも非常に重要な役割を持っておりますので、就労面と生活面の支援を一体的に提供するということが大きな特徴でございます。\n就労面の支援ということで具体的に申し上げますと、就労の相談、それから職場の開拓、さらに職場の実習の支援、一種のジョブコーチということで、自分も職場に行って、実習を自分も実際にやってみるということで、いろいろ問題点なんかについてもチェックをするという形でございます。それから、職場定着のための支援ということで、定期的に訪問して様子を見ていく、激励をするということ。それから実務の援助ということで、これも一緒にやる、その辺が非常に重要でございます。それから、職場環境の調整、これがある意味で非常に重要だというふうに言われております。なかなか知的障害者の方について、上司とか同僚の方の理解を得ていくのが非常に難しい。その辺の環境調整、これをスタッフが一生懸命やっていこうということでございます。\nそれから生活面の支援につきましては、これは当然のことながら、家族あるいはグループホームにお住まいの方につきましては、世話人との協力の中で、ここにありますように、いろいろ特に健康管理、この辺が重要だというふうに言われております。健康管理、金銭管理を含めて、日常生活の支援、その他いろいろきめ細かな支援をしていくということでございます。\nそれから、この支援センターの大きな役割の一つが、この２番目、就労支援ネットワークの整備でございます。地域が一丸となって障害者の方の就労をバックアップしていく、そういったことを目的にしまして、ハローワークをはじめとしまして、商工団体、それから民間の事業所、養護学校、障害者の施設ということで、関係の団体にお集まりをいただいて定期的に連絡会を開催するということで、連携と協力体制をしっかりとってまいりたい、このように考えております。\n以上が障害者の就労支援センターの開設についての報告でございます。"},{"i":124,"speaker":"塚本委員長","text":"報告が終わりました。ご質疑ございますか。"},{"i":125,"speaker":"鈴木（ひ）委員","text":"ここのところには載っていないんですけど、プレス発表を見ると、コーディネーターを４名配置というふうなことで書かれていますけど、コーディネーターという方はどういうふうな方がなっているのかということと、それとあと、対象者はどれくらい考えられているのか、そのことについてちょっとお聞かせください。"},{"i":126,"speaker":"日下部障害者福祉課長","text":"それでは、まずコーディネーターでございますけれども、これは今支援スタッフということで申し上げました。これにつきましては、やはりいろいろ特に知的障害者の方と十分に接して、いろいろ経験を積んだ方でないとなかなか難しいんです。ですから、今既に４名のスタッフは配置しておりますけど、既に就労関係でバックアップをした経験をお持ちの方、あるいは障害者の授産施設での指導経験をお持ちの方、それから特にここの今回の支援センターを受託した「ぴゅあ・さぽーと」、非常に特徴的なんですけれども、実際にそういう障害者の施設での指導員としての経験を持ち、なおかつ障害者の方が実際に働いている民間事業所なんかで一緒にその辺の指導の経験をお持ちの方ということで、そういう経験をお持ちの方をコーディネーターという形で配置しているということです。\nそれから対象者の方なんですけれども、これにつきましては、概算で申しますと、先ほど事務事業概要で大体「愛の手帳」をお持ちの方は１,２００名ということでお話ししましたけれども、１８歳以上で中軽度の知的障害者の方というと、大体その半分なんですね。ただ、知的障害の方は、やはりちょっと年齢が進みますと、なかなか就労までは肉体的にもいろんな面でも難しいということで、大まかにまいりまして、やはり、ほんとうにその対象になりますのは、大体４００名から５００名まで行くかどうかと、そんなところで見込んでいるというところでございます。"},{"i":127,"speaker":"鈴木（ひ）委員","text":"対象者四、五百名で、コーディネーター４名というと、かなり大変だなというふうに思うんですけど、こういう施策そのものはほんとうに待たれていたことで、ほんとうに望まれることだと思いますので、今立ち上がったところということなので、ぜひ前進をさせていただきたいと思います。"},{"i":128,"speaker":"塚本委員長","text":"ほかにございますか。\nないようでしたら、次へ移ります。\n────────────────────────────────────────────\n(2)ファミリー・サタデイ事業について\n(3)平成１５年度学童保育クラブの入会状況について"},{"i":129,"speaker":"塚本委員長","text":"次に、ファミリー・サタデイ事業および平成１５年度学童保育クラブの入会状況について、２本続けてお願いします。"},{"i":130,"speaker":"辻田児童課長","text":"それでは、２本続けて報告させていただきます。\nまず初めに、「ファミリー・サタデイ子育て体験事業実施について」ということでございます。\n事業目的として、核家族化の進展や地域コミュニティの希薄化により、孤立した子育てを行っている家庭が増加している。保護者の交流や子どものふれあう機会の提供が求められている。そのために、これまで共働き等により保育に欠ける家庭への支援を主に行ってきた保育園の施設、それからマンパワーを利用して、月１回特定の土曜日を在宅子育て家庭に開放し、有効活用することで、地域子育ての支援の充実を図るという事業でございます。\nこれは事業実施に際しましては、これまで在宅子育て支援に努めてきた児童センターのほうも幼児クラブであるとか、親子サロンですね。園庭があるところはちびっこプラザというところで、大変少なく、３カ所しかございませんが、そういう形で努力してまいりました。それともう一つ、保育園、ここは施設もあり、園庭もあり、それから子育てのベテランの保育士さんがいるというようなことで、そこが連携して、何か在宅子育て支援、それができないかということで始めた事業でございます。\n事業の実施場所は、地域的なバランスを考えて１０園実施することにいたしました。そしてまず初めに、１番から５番までの児童センター、保育園でこの事業を立ち上げたということでございます。６番から１０番までにつきましては、今までの実施状況等を勘案しながら、９月から実施するということでございます。\nそれから、これは当然上が児童センター、下が保育園というような形のところを選んで今回実施しているわけでございます。\nそれから、事業実施時間および内容ということで、土曜日１０時から午後１時ということで、ここに書かれている懇談であるとか、保護者同士の交流、それから在園児との集団生活体験、それから昼食の提供ということで、保育園で出している給食をこちらのほうで提供するということで、親御さんも同じ物を食べるということで実施しております。\nそれから、利用者の対象でございますけれども、０歳から就学前までということで、児童および保護者、特に私どものほうは父親の参加を非常に進めているということでございます。\nそれから、利用料につきましては、食事代、それから諸経費を入れまして、児童・保護者、それぞれ５００円ということで、今回料金設定をいたしました。\n周知方法につきましては、「広報しながわ」であるとか、ＣＡＴＶのほうでも事業周知で放送したところでございます。それから、各児童センターのポスター掲示であるとか、チラシの配布をしているということでございます。\nこの５番目に東五反田児童センター、６月７日ということで、既に土曜日にこの事業を実施いたしました。朝日新聞が取材に来ていただきまして、大きな形で取り上げていただいて、内容的にも非常に好感の持てる記事になっております。ということで、６月７日の分は過ぎました。２１日、２８日、それぞれ進めてまいります。\nなお、６月７日のときには、これは５月２６日に申し込みを受け付けたんですけど、約２時間で６組、すぐ埋まってしまい、今回も今日から中延児童センターと東大井児童センターで募集しておりますけど、中延児童センターは既に６組決まったということでございます。なお、６月７日、当日東五反田児童センターでは、２組の父親の申し込みがあったんですけど、お一人はどうしても何か仕事の都合で来れなくなってしまったということで、お一人しか参加できませんでした。ただ、私どものほうで、父親参加というのを非常に重視しておりますので、この辺はさらに進めいきたいというぐあいに考えております。\nその次、「平成１５年度学童保育クラブ入会状況」、これは４月１日現在、例年委員会にご報告しているものでございます。３８の学童保育クラブがございます。この中で、定員が１,６２５人に対して、４月１日現在で現員が１,７４７人、定員に対して１２２人のオーバーということでございます。約７.５％のオーバーということで、ちなみに昨年は１,６６６人ということで、８１人オーバーでございました。大体２.何％という形でのオーバーで、さらに現員が増えてきた、申込者が増えてきたという状況でございます。それぞれ、増えたところ、減ったところ、いろいろございます。ただ、なかなかここら辺の増える、減るは、街の状況等によって建物が建つと増える等、予測することが非常に難しい状況でございます。\nただ、この中で、学童保育クラブの入会理由別一覧というのが事務事業概要の７９ページに載っております。ここを見ますと、平成１５年で共働き部分につきましては、およそ１００人弱減っております。これは平成１３年度で比較してございます。それで、母子家庭、父子家庭がそれぞれ増えているという中で、一番増えているのが、自営業者が約１００名近く増えている、自営業者のお子さんが１００名近く増えているということでございます。ここら辺の分析につきましては、今後さらに進めていきたいなというふうに考えております。\n簡単ではございますが、以上でございます。"},{"i":131,"speaker":"塚本委員長","text":"２件について報告が終わりました。ご質疑ございますか。"},{"i":132,"speaker":"須藤委員","text":"学童のほうで、今すまいるスクール等々で若干その辺の変動があろうかと思うんですけども、これは定員に対して現員という、申込者だよというのと、それから現実的にそこに通われる方はどうかなというのを見ていかないと、すまいるスクールとダブったりというようなお子さんたちもいるだろうと思うので、そんなこともまだ今後勉強していきたいと思うんだけど、その辺をカウントしておいていただければと思います。よろしくお願いします。"},{"i":133,"speaker":"飯沼副委員長","text":"ファミリー・サタデイ子育てのことなんですけれども、今のご報告だと、とても期待されている事業のようですけれど、子育て相談を話だけでなくて、実際体験できるということでは、すごくいい施策だなと思うんですけれども、まず一つに、児童課長からご報告があって、児童センターと保育園が連携していくということなんで、具体的にどのように連携をされるのか、新聞の記事を見ると、保育園で子育て相談と、保育園のことしか書かれていないんです。なので、その辺の連携がどうなっているのかと、あと、申し込み方法、受け付け、そして実際にこの子育て相談はどこの場所を使って行われるか教えてください。"},{"i":134,"speaker":"辻田児童課長","text":"まず、連携でございますが、私どもでこの事業を進めていく上で、きちっとそれぞれの児童課と保育課の役割をもう一度整理しようということで、子育て支援全般につきましては、児童課という形での区分けをしてございます。そういう中で、児童センターの幼児クラブとか親子サロンに来た親御さんが、上から見ていると下で楽しそうに遊んでいると。それを見て、ぜひああいうところで、というような声もありました。それを受けて、私どものほう、この事業を始めたわけですけど、この連携につきまして、まず全体の募集、それからＰＲ、そういうようなものにつきましては、陰の力というか、下積みの力というか、そういうような部分につきましては児童課がやる、それから事業の実施につきましては、保育園が全般的に料金の徴収も含めてやるということで、それぞれがお互いに持っている力、一番やりやすい部分で役割分担をして、そしてこの事業を始めたということでございます。\nそれから、申込受付につきましては、ＰＲを当然児童センターでやっております。ただ、受け付けにつきましては、保育園のほうで実施するということで、そこで料金も払っていただくということでございます。\nそれから、子育て相談と申しましても、いわゆる子育て相談に来るのではなく、その中で体験していただくということが主でございますので、幼児の遊びに始まり、子育てのいろんな話、それから保育士さんの貴重な体験から出たいろんなアドバイスですね、そういうようなものを園の中で、または園庭を使って、全体的に使って実施しているという状況でございます。"},{"i":135,"speaker":"飯沼副委員長","text":"受け付けのところとか、下で支えるところを児童課で、実際は保育園でやっていくということですよね。という意味では、中身的な計画というのはどこで立てているのか、児童課と保育課と連携して、内容的なところまで話し合いをしているのかどうか、それが１点と、あと、保育園の土曜日の利用状況というのは、各園によってすごくばらばらで違うと思うんですね。私が心配するのは、体制的にどうなっているのかなというのがまず気になるんですけれども、保育園の職員の方々から出ているニュースによると、土曜日の状況がちょっと具体的に書かれているので、ちょっと読ませていただきたいんですが、土曜日は、正規の保育士３人と非常勤で、子どもは２０人前後出席をしていて、シフト６の当番が来る時間、１０時４５分に遅く出勤する人がいるというんですけれども、それまでの間は正規の保育士２人しかいないといった、こういった状況の中で、これは１０時からでしたかね、始まるのが。\nあともう一点は、０歳の、特に手のかかる０歳のところなんですけれども、土曜日は０歳児が５人出席のときもあり、保育士がファミリー・サタデイの参加者の担当をしたり、懇談ができる状況ではないという、だから、園によって多分違うと思うんですけれども、その辺がこの事業は０歳から就学前までですよね。いろんな年齢で、そのときどきによって多分来られる方が違うと思うんですけれども、園の今の在園児の子どもの状況とあわせて、どういう体制にしていくのかというところを一つお尋ねしたい。"},{"i":136,"speaker":"辻田児童課長","text":"まず初めのお尋ねでございますが、私どものほう、保育園とそれから子育て支援をしている児童課ということで、なかなかその事業の接点がございません。そういう中では、子育てのエキスパートである保育士さんの力、これを使って子育て支援が何とかできないかというような思いがございました。そういう中で、児童センターのほうに親子で来ているお母さん方からの要望もございまして、私どものほうと、それから保育課、それぞれがお互いに連携して何かをやっていこうという形でできたのがこの事業でございます。確かに請け負う部分は保育課の部分が非常に多うございます。それはこの事業の性格上来ることでございまして、決してどちらのほうが負担がかかっている、あちらのほうが負担がかかっていないというようなものではなく、全体の子育て支援という事業の位置づけの中で、一つメニューを私どもが増やしたというぐあいに考えております。"},{"i":137,"speaker":"金子保育課長","text":"ファミリー・サタデイ子育て事業の保育園の体制ということですので、私のほうからご答弁申し上げます。\n委員ご指摘のとおり、土曜日につきましては、各園によって園児の出席の状況は、相当差はございます。園児の出席状況につきましても、これについてはあらかじめ保護者のほうから申し出いただいております。\nそれから、このファミリー・サタデイの申し込みにつきましても、２週間前の月曜日から１週間前の水曜日まで、これを申し込みの基本としておりますので、あらかじめどのような年齢の方がお見えになるか、また、保護者が何人お見えになるか、これも予測できております。ですので、この事業に関しましては、当然事業の実施に遺漏がないよう、また、在園している園児の保育についても遺漏がないように体制を組んで実施しております。実際問題としましては、保護者が来ておりますので、例えば０歳児３対１とかという国等の配置基準がありますけれども、そういった配置基準で考えるのではなくて、先週行いました東五反田保育園におきましては、従来の出勤を予定していた保育士に加えて、初回ですので、園長、副園長が来て対応すると、そういった対応で十分、むしろ余りある対応であったかなというふうな考えは持っております。"},{"i":138,"speaker":"飯沼副委員長","text":"保育園の力をかりる、保育士さんの力をかりるというのも、ほんとうに子育てのところでは児童課の職員よりも、小さい子になれている、プロであるということでは、ほんとうに願ってもないことだろうなと思います。そういった面で、今体制のことで遺漏のないようにということなんで、十分その辺を配慮していただきたいというのと、今園長、副園長対応とおっしゃったんですけれども、職員のところの体制がとれないような状況だったら、園長とか副園長が出て責任を持って行うということなのでしょうか。\nその点がもう一点と、あと、遺漏のないということでは、保護者つきでいらっしゃるんで、見えたお子さんのところはいいと思うんですけれども、在園児で、既に土曜日に保育を受けているお子さんの状況についても、多分この辺は保育課でないと細やかな配慮はできないなと思うんですけれども、土曜日というのは、職員体制が４分の１なので、クラスによっては担任の先生がいないクラスもある。あと、お友達が少なくて、混合の保育をしたり、あとはいつもと違った月曜日から金曜日までとは違った状況の中で保育をされるという中に、その辺に、お母さんと一緒に、お父さんと一緒に来る初めてのお子さんを受け入れるというところでの子どもの動揺があるのではないかなという懸念もされるんですが、その点１点と、あと、在園児の保護者の方に、この内容について説明があったかどうか。その点をお答えいただきたいと思います。"},{"i":139,"speaker":"金子保育課長","text":"まず、東五反田保育園で初回やりましたけれども、これは実施主体が保育課保育園であるということから、当然第１責任者である園長ならびに第２責任者である副園長は、当然出席すべきものというふうに考えておりましたので、これについては出席するように私のほうから指示しております。\nそれから、在園児の対応の部分ですけれども、ご指摘のとおり、ほとんどの保育園でそのように４分の１の保育士が出勤するというふうな体制をとっておりますが、ただ、委員ご指摘のとおり、土曜日に事業を実施する場合もありますし、あるいは子どもの出席状況が多くなったり、少なくなったりということもありますので、これについては遺漏なく円滑に対応するのが筋だと思っておりますので、こういった４分の１ということに固定的に考えるのではなくて、対応すべきものというふうに考えております。現実には、通常の職員プラス園長、副園長で先ほど申し上げたとおりの実態であったということを申し上げておきたいと思います。\nそれから、在園児の子どもの動揺ということですが、私も実際、東五反田保育園のほうに見に行って、その辺も懸念していたところでありますが、実際のところ、そこにはきちっと保育士も対応しておりましたので、この子どもの動揺ということに関しては見られなかったというふうに申し上げておきたいと思います。\nそれから、在園児の保護者への周知ですけれども、これにつきましては、実施する園でこういうふうな新しい事業を始めますよということで掲示を行っているものでございます。"},{"i":140,"speaker":"飯沼副委員長","text":"最後に要望ですけれども、在宅の子育てを支えていくとてもよい企画だと思うんです。でも、相手が０歳から就学前という小さいお子さんなので、十分に配慮してほしいし、やっぱり何よりもこの人手が十分にないと安全面もすごく不安だし、せっかくの企画に傷がついてしまうと思うので、利用者である区民の皆さんと職員の意見を十分に聞いて、これからなので進めていただきたいと要望して終わります。"},{"i":141,"speaker":"鈴木（ひ）委員","text":"学童保育クラブの入会状況についてお聞きしたいと思います。\nこの表を見ると、中延の学童は３４名の定員に対して６４名で、私は中延に住んでいるんですけど、西中延学童保育クラブも４０名に対して６１名で、先日、西中延学童保育クラブと中延学童保育クラブに見学に行ってきたんですけど、西中延はほんとうに小さいこれぐらいのテーブルに１０人ぐらいが一緒になっておやつを食べるというふうな状況でしたけれども、ほんとうに学童保育の入会状況というのが、今も説明ありましたけど、年々定員に対しての現員のパーセンテージが上がっているという状況があると思うんですけれども、今後これに対して推移も含めて、そして対応についてどういうふうに考えられているのか、そのことを１点お聞かせいただきたいと思います。\nそしてもう一つ、特にマンションとか公団とか、できる地域があると思うんですけど、東海学童がなくなるときもかなり論議になりましたけど、東品川三・四丁目とか、東大井一丁目、そこら辺のところでは、かなりこれからも建設のラッシュ、公団もできますし、建設中のマンションもかなりあるという状況だと思うんですけれども、そしてそこのところでは、例えば城南第二にすまいるスクールがもう既にできていますけども、それにもかかわらず定員が３０名のところを、今回も４２名という状況になっていますけれども、そこら辺のところがどれぐらい増えるというふうに考えられているのか、また、それに対してどういう対応をするということで考えられているのかについてお聞かせいただきたいと思います。"},{"i":142,"speaker":"塚本委員長","text":"鈴木委員、本件は当委員会の調査事項のかなりの重要な部分を占めておりますので、後ほど調査事項をどういうふうに取り上げていくかということをお諮りいたします。今日は時間が非常にタイトでございますので、後のお答えと議論の対象にしたいと思いますが、いかがでございましょうか。"},{"i":143,"speaker":"鈴木（ひ）委員","text":"結構です。"},{"i":144,"speaker":"塚本委員長","text":"ということでございます。\nでは、本件を終了いたします。\n────────────────────────────────────────────\n(4)平成１５年度保育園の入園状況について\n(5)「プリスクール西五反田」の進捗状況について"},{"i":145,"speaker":"塚本委員長","text":"最後の報告事項(4)、(5)、金子保育課長、お願いいたします。"},{"i":146,"speaker":"金子保育課長","text":"それでは私から、まず「平成１５年度の保育園の入園状況について」ご説明申し上げます。\nＡ４判１枚の紙でかなり数字が多くて見づらいかと思いますが、ご容赦いただきたいと思います。\nこの表の見方ですけれども、上のほうに説明の欄がありますとおり、上の左から、まず夜間保育の状況ということで、☆が午後８時半まで、それから、★が夜１０時までの夜間保育の状況をあらわしております。それから、その一つ右の欄が０歳児保育の実施状況ということで、○が０歳児保育を実施している状況でございます。\nそれから保育園名、その右に行きますと、定員が３歳未満の定員、３歳以上の定員区分で、その右が定員のトータルというふうになっております。それから、その右が在園児数、ちょっと抜けておりまして申しわけありませんが、在園児数の各年齢ごと、それから０、１、２歳の小計、それから３、４、５歳の年齢ごとと、その小計、一番右が在園児の合計というふうな欄の構成になっております。\n区立の保育園の合計ですが、下から１０行目あたりに３８番と３９番の間に小計という欄がございます。こちらを見ていただきますと、左から３歳未満が１,２７０名の定員、３歳以上で１,９７１名の定員、あわせて３,２４１名の定員となっておりますが、在園の状況としましては、右に四つ行っていただいて、１,３７７名が３歳未満の在園児で、充足率が１０８.４％でございます。さらに右に４つ行きますと１,９５０名という数字がありますが、これが３歳以上の在籍園児数で、充足率が９８.９％でございます。一番右の欄が３,３２７名、これは区立保育園全体の在園児数で、充足率が１０２.７％となっております。\nそれから、一番下に行きますと、下から２番目が私立の計なんですが、一番下が私立、区立の合計でございます。一番左が１,５７３名、これが３歳未満の定員で、２,２４６名が３歳以上、それから３,８１９名が定員の合計でございます。公・私立合計の在園児数が右に四つ行きまして１,７０７名、これが３歳未満の在園児数で、充足率が１０８.５％、それからさらに右に四つ行きまして２,２２０名、これが３歳以上で、充足率が９８.８％、一番右の下の数字が３,９２７名、公・私立合計の在園児数で、全体として１０２.８％の充足率になっております。\n昨年の４月と比べますと、公立では昨年９月に開園しました教育委員会の所管ですが、二葉つぼみ保育園が定員４３名で開設しておりまして、また本年４月には、私立のどんぐり保育園の第２分園が開設され、本園と分園であわせまして４３名定員を増やしておりますので、昨年４月と比べると計８６名の定員増というふうになってございます。\n表から離れますが、入園の待機児の数でございます。こちらは４月１日現在で、０歳児から５歳児までトータルで１３８名となっています。昨年は１５３名でしたので、若干減少しております。\nなお、待機児の定義につきましては、昨年度から厚生労働省の指示で定義自体が新しくなっております。品川区の傾向としましては、平成１２年度を底としまして、申込者の数が増加傾向にあります。今年度につきましては、先ほどの定員増、また入園弾力化等により、待機児童は減少しております。\n以上で入園状況のほうの簡単な説明を終わらせていただきます。\n続きまして、「プリスクール西五反田」の進捗状況についてご説明申し上げます。\nＡ４の紙とＡ３の紙が２枚ほどついているかと思いますが、まずＡ４の紙のほうからご説明申し上げたいと思います。\n既に今年度の予算のところでご説明があったかと思いますが、既存の幼稚園の枠にとらわれない、あるいは保育園の枠にとらわれない幼児教育施設と保育園の新たな連携として、幼児教育と保育を融合した就学前施設として設置を考えているものでございます。運営につきましては、私立幼稚園の優れた教育力を活用するために、品川区で幼児教育を中心となって担ってきた区内の私立幼稚園の園長の有志の方々が設立するＮＰＯ法人に委託する予定でございます。そういった目的のもとに、事業内容ですが、トータルを品川型就学前施設と考えておりまして、３歳から５歳については品川型幼児教育施設で、これにつきましては、幼稚園の認可基準を満たしつつも、あえて規制や慣行にとらわれない斬新な発想で事業を展開するためにあえて認可をとらないという考えでおります。それから、０歳から２歳に関しましては、児童福祉法に基づく認可保育園、さらに子育て支援センターを併設する予定でおります。\nそれぞれの中身ですが、(1)にありますとおり、まず幼児教育施設につきましては、定員５４人、開所時間は午前７時３０分から午後６時３０分まで、プラスして延長保育で２時間、午後８時３０分までということで考えております。ここは幼稚園型教育を想定しておりますので、細かいところはこれからの検討になりますが、例えば９時から２時までをコアタイムと設定いたしまして、従来の保育園ですと、登園、降園の時間というのがある程度フリーですけれども、例えば９時から２時に関しては、必ず登園をいただくと、こういうふうな格好で考えているものでございます。\nそれから(2)の認可保育園につきましては、予定定員が４６人、開所時間が７時３０分から１８時３０分、延長保育がさらに２時間ということで、これは(1)の幼児教育施設と同じでございます。さらに、子育て支援センターにつきましては、子育て支援事業や子育て相談、一時預かり等々を想定しております。\nそれから、建築の概要ですが、図面は後ほどご覧いただきますが、西五反田三丁目９番、災害対策大崎職員寮の跡地ということで建設を予定しております。規模は敷地面積が１,４７４.９４平米、建築面積が５８３.９７平米、延べ床面積が９９５.０６平米で、鉄筋コンクリートの２階建てを想定しております。\nスケジュールとしましては、現在建設工事の着工が８月で、竣工が平成１６年４月、施設の開設が１６年６月と想定しております。解体工事につきましては、既に５月１３日から始まっているところでございます。\nＡ３のほうの資料をご覧いただきたいと思います。面積関係につきましては、先ほどちょっとご説明したとおり、プラスごみ置き場がカウントされますので、４.０５平米というものがプラスでカウントされるということです。右側の案内図にありますとおり、これは今日の報告にもありました荏原市場跡地の西五反田の複合施設のちょうど対岸になります。川からこの施設、その山手通り側、川と反対側のほうには、既存の西五反田保育園があるというものでございます。\n１枚おめくりいただいた裏が１階の平面図になります。右斜め上のほうが北になりまして、ちょうどこの図面で言いますと、一番右が目黒川で、川に沿った道路が、７メートルほどの道路が右側にある。この図面で言うと、下側が４.５メートル幅の道路になっておりまして、左側のほうが先ほど申し上げた既存の西五反田保育園ならびにシルバーセンターが併設する建物があるということです。この図面で言うと、上のほうは民地でございます。図面につきましては、ちょうど左側の道路沿いのところから入ってきて、真ん中がプリスクールの入口というふうに想定しております。入りまして、右のところが事務室、それから右のほうにずっとまいりますと、職員等のトイレ、ならびに倉庫の次から３歳児、４歳児、５歳児、それから上に遊戯室、いわゆるホールというものをできる限り柱と壁をなくすということで設計しているものでございます。それから、右側のほうに、屋外階段とありますのは、２階のほうで説明します子育て支援センターの入口になります。それから左のほうに戻っていただいて、入ってすぐの左側は、厨房をつくる予定としております。\nこのような建物の配置になったそもそもの理由は、右側の斜め、この敷地内の右側の斜めに点線でＬ字型に囲まれた部分がちょっとわかりにくいかと思いますが、その存在がわかると思うんですが、このＬ字型の部分といいますのは、この地区の雨水を貯留する施設が地下にありまして、ここをいじるとなると、相当大がかりな工事で経費も相当かかりますので、今までの職員の待機寮もそうだったんですが、今度の建物もそこの施設をいじらないような形で建てて、経費の節減に努めているということでございます。\nそれからＡ３の２枚目の紙のほうに移っていただきたいと思います。２枚目の紙が２階部分になります。左側のほうの内階段を上がっていただきますと、左側の部分が、０歳、１歳、２歳の各部屋になっておりまして、ここの部分も壁をつくらない形で、できる限り有効に使おうというふうな設計にしております。\nそれから、真ん中の廊下のところにドアの仕切りがありますが、そこから右側が子育て支援センターの部分になります。一番右側の屋外階段のところから上がってきていただきますと玄関がありまして、玄関を入りますと、右側に管理室および相談のコーナーがあります。左側につきましては、交流スペースと地域活動室ということで、部屋の構成を考えております。\n最後、一番最後のページをご覧いただきたいと思います。現在想定している開園まで向けたスケジュールでございます。上の枠につきましては、ＮＰＯ法人、先ほど申し上げたとおり私立幼稚園の園長有志の方が、これから設立する予定というふうに申し上げましたが、そのＮＰＯ法人の予定でございまして、現在申請書類等の作成を計画しておりますし、８月には申請をして、１０月から、公告期間というのが２カ月必要ですので、１０月ごろから審査を東京都のほうでお願いして、１２月には認証の取得ができればというふうに思っております。\nそれから、ハード関係その他が下のほうになりますが、まず工事関係、先ほど申し上げましたとおり、解体工事が５月１３日から始まりまして、それに先立って５月７日には解体工事の説明会を地元の大崎第一地域センターで開かせていただいております。\nそれから、６月４日に建設の説明会を終えております。あと、８月には工事の説明会を開催する予定になっております。その他工事関係、それから求人等、あるいは園児の募集等、現在想定しているところのスケジュールを載せていまして、建物が４月の終わりには完成しますので、それ以降、当該建物を使って実地研修、６月から開園する、こういうふうな予定で現在想定しているものでございます。\n以上、簡単ですが、説明とさせていただきます。"},{"i":147,"speaker":"塚本委員長","text":"これもまた大変中身の濃い報告でございますが、時間がございませんので、次回に実質的な質疑をいたしたいと思いますが、いかがでございますか。質問事項だけ通告をしたいというならば、お願いしますけど、質疑応答ということにはならないと思いますが、ございますか。\nよろしいですか。\n〔「はい」と呼ぶ者あり〕"},{"i":148,"speaker":"塚本委員長","text":"それでは、そのように扱わさせていただきます。\n休憩時間をとるつもりでおりましたけれども、会議の運営上休憩をとらないというはかりにさせていただきたいと思います。\n────────────────────────────────────────────\n４．今年度の委員会運営について"},{"i":149,"speaker":"塚本委員長","text":"それでは、報告事項が終わりまして、４の今年度の委員会運営についてを議題といたします。\n実質１年間の初めでございますので、またご案内のとおり築舘議長が議会の活性化のもとは、各委員会での質疑応答、委員会が独自の視点でもって調査事項を調べていくということにあるというお考えをお示しになっております。それを受けまして、ぜひ皆様、我々厚生委員会の課題を、焦点を絞っていきたいということをお願いしたいと思います。\nこの場でご意見がありましたら、その点に関していただきたいと思いますけれども、次回、３０日の委員会ですけども、２０日をめどに委員長もしくは書記方のほうに、それぞれこんなことを焦点に当てたいんだというご意向をお示しいただければ、それをもとに次回の委員会の中で決定を見ていきたいと思いますので、どうぞよろしくお願い申し上げます。\n何かございますればということでございます。\nよろしゅうございますか。\n〔「はい」と呼ぶ者あり〕\n────────────────────────────────────────────\n５．その他\n(1)特別区委員長会の派遣について\n(2)その他"},{"i":150,"speaker":"塚本委員長","text":"それでは、その他、(1)の特別区委員長会の派遣についてを議題にいたしますが、ご案内のとおり、特別区の議長会において、委員長会のあり方が検討されまして、従来の定例的な委員長会活動はしないということになりました。今後は２３区共通の課題に対して、各区の常任委員会の委員長による調査研究が必要になった場合には、議長会会長が委員長会を召集する、こういう仕切りに変わりました。ご案内のとおりでございます。ということでございますが、特別区福祉委員長会が召集された場合のことを想定しておかなきゃいけないということで、お手元に配付のとおり、召集された場合は、正または副委員長を呼んでくれよという手続をとるということなんでございますけれども、どうぞご理解をいただきたい。\nよろしゅうございますか。\n〔「はい」と呼ぶ者あり〕"},{"i":151,"speaker":"塚本委員長","text":"それでは、その他のその他でございます。\nご案内のとおり、統一地方選挙がありましたので、議会の構成が１月近く遅れております。そして、視察のことも視野に入れておかなければいけないと思います。調査事項を次回で立てますけれども、それの裏づけとして、こういうことも現地で見ておきたいということ、視察の考え方も各会派でご議論いただきたいということでございます。どうぞよろしくお願いいたします。\n委員長のほうから委員会運営の考え方についてお示しいたしましたけれども、各委員のほうからございましたら、改めてお願いします。"},{"i":152,"speaker":"須藤委員","text":"今日いろいろな報告や事務事業概要をやったんですけども、報告事項あるいは調査事項によっては、各理事者全員並んでいなくてもいい場面があると思うので、その辺、委員長、ご判断していただいて、報告事項、あるいはどうしてもというときには説明員としておいでいただきますけど、その辺を調整していただければ、よろしくお願いします。"},{"i":153,"speaker":"塚本委員長","text":"ありがとうございます。\nほかに運営について。\nよろしゅうございますか。\nそれでは、以上をもちまして、厚生委員会を閉会いたします。長時間大変ありがとうございました。\n○午後４時４５分閉会"}]});
